window.__IM_G6_UNITS__ = window.__IM_G6_UNITS__ || {};
window.__IM_G6_UNITS__[1] = {"schemaVersion":"1.0.0","number":1,"code":"unit01","title":"Area and Surface Area","bilingual":{"titleVi":"Diện Tích & Diện Tích Toàn Phần (Area and Surface Area)","summaryVi":"Học cách tính diện tích hình phẳng bằng phương pháp cắt ghép (Decompose & Rearrange): Hình bình hành (A = b·h), Hình tam giác (A = ½·b·h), Đa giác bất kỳ; khai triển hình khối (Nets) để tính Diện tích toàn phần (Surface Area) của hình lăng trụ, hình chóp và hình lập phương.","cues":[{"en":"decompose and rearrange","vi":"Cắt nhỏ và ghép lại hình để giữ nguyên diện tích","math":"Area preserved"},{"en":"base (b) and height (h)","vi":"Cạnh đáy và Đường cao (luôn vuông góc với đáy!)","math":"b ⊥ h"},{"en":"parallelogram / triangle","vi":"Hình bình hành / Hình tam giác","math":"bh / ½bh"},{"en":"net / surface area / polyhedron","vi":"Hình khai triển / Diện tích toàn phần / Khối đa diện","math":"SA (sq units)"}],"trapsVi":["Đường cao (Height) của hình bình hành hay tam giác LUÔN phải vuông góc với đáy (Base) — KHÔNG bao giờ lấy cạnh xiên làm chiều cao!","Phân biệt Surface Area (Diện tích toàn phần — đơn vị vuông: cm²) với Volume (Thể tích — đơn vị lập phương: cm³)."]},"totalActivities":55,"totalProblems":105,"lessons":[{"uid":"img6.u01.l01","number":1,"title":"Tiling the Plane","introText":"Let’s look at tiling patterns and think about area.","activities":[{"title":"1.1: Which One Doesn’t Belong: Tilings","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Which pattern doesn’t belong?</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27188\" data-record-model=\"ImageFile\"><img alt=\"Four patterns of tiles labeled A, B, C, and D. \" class=\"h-max-height--18-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/rgoR2UCTWNPbvt6VaGZeMZTL\">\n                \n              </figure>\n              \n            </div>"},{"title":"1.2: More Red, Green, or Blue?","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Your teacher will assign you to look at Pattern A or Pattern B.</p>\n              <p>In your pattern, which shapes cover more of the plane: blue rhombuses, red trapezoids, or green triangles? Explain how you know.</p>\n              <p>You may use the sliders and the shapes in this applet to help. Explore what you can see or hide, and what you can move or turn.</p>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4258\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4258-1\"></div>\n              </div>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>On graph paper, create a tiling pattern so that:</p>\n                    <ul>\n                      <li>The pattern has at least two different shapes.</li>\n                      <li>The same amount of the plane is covered by each type of shape.\n                      </li>\n                    </ul>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>In this lesson, we learned about <em>tiling</em> the plane, which means covering a two-dimensional region with copies of the same shape or shapes such that there are no gaps or overlaps. </p>\n              <p>Then, we compared tiling patterns and the shapes in them. In thinking about which patterns and shapes cover more of the plane, we have started to reason about <strong>area</strong>.</p>\n              <p>We will continue this work, and to learn how to use mathematical tools strategically to help us do mathematics.</p>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Which square—large, medium, or small—covers more of the plane? Explain your reasoning.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29330\" data-record-model=\"ImageFile\"><img alt=\"A plane composed of a series of squares. There are 5 large squares, 10 medium squares, and 10 small squares.\" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/YNVEA7SiP8dZ9T1tLChh3CAz\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--column g--half g--content g--col-2 g--row-1\"></div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Draw three different quadrilaterals, each with an area of 12 square units.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27247\" data-record-model=\"ImageFile\"><img alt=\"Image of a grid.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vupNoA5g96AkAtsSrCipKyG6\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Use copies of the rectangle to show how a rectangle could:</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                  <p>a. tile the plane.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29325\" data-record-model=\"ImageFile\"><img alt=\"shaded rectangle on a grid. length = 3 units, height = 2 units.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/hYpNxoZYVRjJqTyNW6qABUog\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                  <p>b. <em>not</em> tile the plane.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29325\" data-record-model=\"ImageFile\"><img alt=\"shaded rectangle on a grid. length = 3 units, height = 2 units.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/hYpNxoZYVRjJqTyNW6qABUog\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>The area of this shape is 24 square units. Which of these statements is true about the area? Select <strong>all</strong> that apply.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29326\" data-record-model=\"ImageFile\"><img alt=\"A figure on a grid.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/TTjUCPg7x2Nod8LfNn15uGVV\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>The area can be found by counting the number of squares that touch the edge of the shape.</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>It takes 24 grid squares to cover the shape without gaps and overlaps.</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>The area can be found by multiplying the sides lengths that are 6 units and 4 units.</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>The area can be found by counting the grid squares inside the shape.</p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p>The area can be found by adding <span class=\"math math-repaired\">\\(4 \\times 3\\)</span> and <span class=\"math math-repaired\">\\(6 \\times 2\\)</span>.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Here are two copies of the same figure. Show two different ways for finding the area of the shaded region. All angles are right angles.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29327\" data-record-model=\"ImageFile\"><img alt=\"A geometric figure with straight sides and right angles.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Q8NUV7YAQGfSBPFANCxgvydX\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29327\" data-record-model=\"ImageFile\"><img alt=\"A geometric figure with straight sides and right angles.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Q8NUV7YAQGfSBPFANCxgvydX\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Which shape has a larger area: a rectangle that is 7 inches by <span class=\"math math-repaired\" data-png-file-id=\"9491\">\\(\\frac 34\\)</span> inch, or a square with side length of <span class=\"math math-repaired\" data-png-file-id=\"8184\">\\(2 \\frac12\\)</span> inches? Show your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l02","number":2,"title":"Finding Area by Decomposing and Rearranging","introText":"Let’s create shapes and find their areas.","activities":[{"title":"2.1: What is Area?","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>You may recall that the term <strong>area </strong>tells us something about the number of squares inside a two-dimensional shape.</p>\n              <ol>\n                <li>Here are four drawings that each show squares inside a shape. Select <strong>all </strong>drawings whose squares could be used to find the area of the shape. Be prepared to explain your reasoning.\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27192\" data-record-model=\"ImageFile\"><img alt=\"Four drawings that each show squares inside a shape.\" class=\"h-max-height--16-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/RN99bYCzEWoawXRwk9G59MpP\">\n                    \n                  </figure>\n                </li>\n                <li>Write a definition of area that includes all the information that you think is important. \n                </li>\n              </ol>\n            </div>"},{"title":"2.2: Composing Shapes","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>This applet has one square and some small, medium, and large right triangles. The area of the square is 1 square unit.</p>\n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4259\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4259-1\"></div>\n              </div>\n              <p>Click on a shape and drag to move it. Grab the point at the vertex and drag to turn it.</p>\n              <ol>\n                <li>\n                  <p>Notice that you can put together two small triangles to make a square. What is the area of the square composed of two small triangles? Be prepared to explain your reasoning.</p>\n                </li>\n                <li>\n                  <p>Use your shapes to create a new shape with an area of 1 square unit that is not a square. Draw your shape on paper and label it with its area.</p>\n                </li>\n                <li>\n                  <p>Use your shapes to create a new shape with an area of 2 square units. Draw your shape and label it with its area.</p>\n                </li>\n                <li>\n                  <p>Use your shapes to create a <em>different</em> shape with an area of 2 square units. Draw your shape and label it with its area.</p>\n                </li>\n                <li>\n                  <p>Use your shapes to create a new shape with an area of 4 square units. Draw your shape and label it with its area.</p>\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Find a way to use all of your pieces to compose a single large square. What is the area of this large square?</p>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"2.3: Tangram Triangles","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Recall that the area of the square you saw earlier is 1 square unit. Complete each statement and explain your reasoning.</p>\n              <ol>\n                <li>The area of the small triangle is ____________ square units. I know this because . . .<!--whitespace-->\n                </li>\n                <li>The area of the medium triangle is ____________ square units. I know this because . . .<!--whitespace-->\n                </li>\n                <li>The area of the large triangle is ____________ square units. I know this because . . .</li>\n              </ol>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4260\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4260-2\"></div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here are two important principles for finding <strong>area</strong>:</p>\n              <ol>\n                <li>\n                  <p>If two figures can be placed one on top of the other so that they match up exactly, then they have the <em>same area</em>.</p>\n                </li>\n                <li>\n                  <p>We can <strong>decompose</strong> a figure (break a figure into pieces) and <strong>rearrange</strong> the pieces (move the pieces around) to find its area.</p>\n                </li>\n              </ol>\n              <p>Here are illustrations of the two principles.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26701\" data-record-model=\"ImageFile\"><img alt=\"Images of squares and triangles being decomposed and composed to form different shapes. \" class=\"h-max-height--16-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/nGuHQmCudF79Z2ZybFpKxKMC\">\n                \n              </figure>\n              <p class=\"img-tag-relocated-by-embedder\">​</p>\n              <ul>\n                <li>Each square on the left can be decomposed into 2 triangles. These triangles can be rearranged into a large triangle. So the large triangle has the <em>same area</em> as the 2 squares.</li>\n                <li>\n                  <p>Similarly, the large triangle on the right can be decomposed into 4 equal triangles. The triangles can be rearranged to form 2 squares. If each square has an area of 1 square unit, then the area of the large triangle is 2 square units. We also can say that each small triangle has an area of <span class=\"math math-repaired\">\\(\\frac12\\)</span> square unit.</p>\n                </li>\n              </ul>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>The diagonal of a rectangle is shown.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29335\" data-record-model=\"ImageFile\"><img alt=\"rectangle on a grid with a diagonal drawn from top left to bottom right corner. base = 3 units, height = 2 untis.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/yMqoPG9AEd1w3bV9582e8X1D\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  <ol>\n                    <li>\n                      <p>Decompose the rectangle along the diagonal, and recompose the two pieces to make a <em>different</em> shape.</p>\n                    </li>\n                    <li>\n                      <p>How does the area of this new shape compare to the area of the original rectangle? Explain how you know.</p>\n                    </li>\n                  </ol>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Priya decomposed a square into 16 smaller, equal-size squares and then cut out 4 of the small squares and attached them around the outside of original square to make a new figure.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                  <p>How does the area of her new figure compare with that of the original square?</p>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--row-1 g--two-third\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29332\" data-record-model=\"ImageFile\"><img alt=\"4 by 4 square on left. Irregular shape composed of unit squares on right.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/CsX48qGcoLC1EwGwUycdmzGu\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>The area of the new figure is greater.</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>The two figures have the same area.</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>The area of the original square is greater.</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>We don’t know because neither the side length nor the area of the original square is known.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>The area of the square is 1 square unit. Two small triangles can be put together to make a square or to make a medium triangle.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29331\" data-record-model=\"ImageFile\"><img alt=\"Three figures. A square, a small triangle, and a medium triangle.\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/3wq8HvBqNaX5mMHJDf2E3S3F\">\n              \n            </figure>\n            <p>Which figure also has an area of <span class=\"math math-repaired\" data-png-file-id=\"35331\">\\(1\\frac 12\\)</span> square units? Select <strong>all</strong> that apply.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29333\" data-record-model=\"ImageFile\"><img alt=\"Four figures labeled A, B, C, and D.\" class=\"h-max-height--12-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/V3Rda6AXRfgnifKtwjnspRw6\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>Figure A</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>Figure B</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>Figure C</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>Figure D</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>The area of a rectangular playground is 78 square meters. If the length of the playground is 13 meters, what is its width?</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 1.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>A student said, “We can’t find the area of the shaded region because the shape has many different measurements, instead of just a length and a width that we could multiply.”</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29328\" data-record-model=\"ImageFile\"><img alt=\"A multi-sided figure.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/DhqcDGtYtF2joLoyUSU9fG77\">\n              \n            </figure>\n            <p>Explain why the student’s statement about area is incorrect.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 1.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l03","number":3,"title":"Reasoning to Find Area","introText":"Let’s decompose and rearrange shapes to find their areas.","activities":[{"title":"3.1: Comparing Regions","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Is the area of Figure A greater than, less than, or equal to the area of the shaded region in Figure B? Be prepared to explain your reasoning.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27203\" data-record-model=\"ImageFile\"><img alt=\"Square A, shaded. Square B identical to A, with a small shaded square removed in the middle and a small shaded square appended to its side.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/etMDgYdD51AJJ2HCr6eDW6jC\">\n                \n              </figure>\n            </div>"},{"title":"3.2: On the Grid","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Each grid square is 1 square unit. Find the area, in square units, of each shaded region without counting every square. Be prepared to explain your reasoning.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27205\" data-record-model=\"ImageFile\"><img alt=\"Four figures, each on a white square grid. \" class=\"h-max-height--16-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/qzFvtghh4zzdnxghxeLd6aQA\">\n                \n              </figure>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Rearrange the triangles from Figure C so they fit inside Figure D. Draw and color a diagram of your work. </p>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"3.3: Off the Grid","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Find the area of the shaded region(s) of each figure. Explain or show your reasoning.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27209\" data-record-model=\"ImageFile\"><img alt=\"3 figures labeled A, B, C.\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Barv3HtKUXJYULZi85GZywoz\">\n                \n              </figure>\n              \n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-video-link\" data-embedder-target=\"web\" data-record-id=\"145\" data-record-model=\"VideoLink\"><iframe allowfullscreen=\"true\" frameborder=\"0\" height=\"360\" mozillaallowfullscreen=\"true\" safariallowfullscreen=\"true\" src=\"https://player.vimeo.com/video/443554693\" width=\"640\"></iframe>\n                <figcaption class=\"c-figcaption\">Video <em>VLS G6U1V1 Reasoning to Find Area (Lessons 1–3, 11)</em> available at <a href=\"https://player.vimeo.com/video/443554693\">https://player.vimeo.com/video/443554693</a>.</figcaption>\n              </figure>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Find the area of each shaded region. Show your reasoning.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29338\" data-record-model=\"ImageFile\"><img alt=\"3 figures on a grid labeled A, B, C.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/FpCukLdcaxLBKn6HZRsxPfvU\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Find the area of each shaded region. Show or explain your reasoning.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29339\" data-record-model=\"ImageFile\"><img alt=\"4 figures labeled A, B, C, D.\" class=\"h-max-height--21-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Bb6GhX6Ua9ZT8XAPsQL4JV31\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Two plots of land have very different shapes. Noah said that both plots of land have the same area.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29344\" data-record-model=\"ImageFile\"><img alt=\"Two shapes labeled “plot A” and “plot B”.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/sdzePpjwxeJzFKUdQ2MEpKKq\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  <p>Do you agree with Noah? Explain your reasoning.</p>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>A homeowner is deciding on the size of tiles to use to fully tile a rectangular wall in her bathroom that is 80 inches by 40 inches. The tiles are squares and come in three side lengths: 8 inches, 4 inches, and 2 inches. State if you agree with each statement about the tiles. Explain your reasoning.</p>\n            <ol>\n              <li>Regardless of the size she chooses, she will need the same number of tiles.</li>\n              <li>Regardless of the size she chooses, the area of the wall that is being tiled is the same.</li>\n              <li>She will need two 2-inch tiles to cover the same area as one 4-inch tile.</li>\n              <li>She will need four 4-inch tiles to cover the same area as one 8-inch tile.</li>\n              <li>If she chooses the 8-inch tiles, she will need a quarter as many tiles as she would with 2-inch tiles.</li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 2.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l04","number":4,"title":"Parallelograms","introText":"Let’s investigate the features and area of parallelograms.","activities":[{"title":"4.1: Features of a Parallelogram","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Figures A, B, and C are <strong>parallelograms</strong>. Figures D, E, and F are <em>not</em> parallelograms. </p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27211\" data-record-model=\"ImageFile\"><img alt=\"Six figures on a grid labeled A--F.\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/gYypJqW5vsfMY7teA5rqk1yd\">\n                \n              </figure>\n              <p>Study the examples and non-examples. What do you notice about:</p>\n              <ol>\n                <li>the number of sides that a parallelogram has?\n                </li>\n                <li>opposite sides of a parallelogram?\n                </li>\n                <li>opposite angles of a parallelogram?\n                </li>\n              </ol>\n            </div>"},{"title":"4.2: Area of a Parallelogram","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Find the area of the parallelogram and explain your reasoning.</p>\n                  \n                  <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4261\" data-record-model=\"GeogebraFile\">\n                    <div class=\"ggb-base-64-data\" data-parameters='{\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                    <div class=\"ggb-applet-container\" id=\"GeogebraFile-4261-1\"></div>\n                  </div>\n                </li>\n                <li>\n                  <p>Change the parallelogram by dragging the green points at its vertices. Find its area and explain your reasoning.</p>\n                  \n                  <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4262\" data-record-model=\"GeogebraFile\">\n                    <div class=\"ggb-base-64-data\" data-parameters='{\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                    <div class=\"ggb-applet-container\" id=\"GeogebraFile-4262-2\"></div>\n                  </div>\n                </li>\n                <li>If you used the polygons on the side, how were they helpful? If you did not, could you use one or more of the polygons to show another way to find the area of the parallelogram?</li>\n              </ol>\n            </div>"},{"title":"4.3: Lots of Parallelograms","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Find the area of each parallelogram. Show your reasoning.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27219\" data-record-model=\"ImageFile\"><img alt=\"Two figures on a grid: parallelogram A and parallelogram B.\" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/9Qrf4qFRLaF4Vq7eT6GRBsNN\">\n                \n              </figure>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27220\" data-record-model=\"ImageFile\"><img alt=\"Parallelogram C has base 6, height 4, and diagonal length 4.5.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/MP62sS386kr4F2pWMZZC66Cb\">\n                \n              </figure>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>A <strong>parallelogram</strong> is a quadrilateral (it has four sides). The opposite sides of a parallelogram are parallel. It is also true that the opposite sides of a parallelogram have equal length, and the opposite angles of a parallelogram have equal measure.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26707\" data-record-model=\"ImageFile\"><img alt=\"Two paralllelograms with the angles and side lengths provided.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/C6h2pFNck6LYugWcU7zsdE5q\">\n                \n              </figure>\n              <p>There are several strategies for finding the area of a<strong> parallelogram</strong>.</p>\n              <ul>\n                <li>We can decompose and rearrange a parallelogram to form a rectangle. Here are three ways:\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26708\" data-record-model=\"ImageFile\"><img alt=\"Three identical parallelograms on separate grids, each has a base of four units and a height of three units.\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vmcxqm8dee1DvdLuGyFSSMNV\">\n                    \n                  </figure>\n                </li>\n                <li>We can enclose the parallelogram and then subtract the area of the two triangles in the corner.\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26709\" data-record-model=\"ImageFile\"><img alt=\"Two drawings of parallelograms on grids.\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/AB6SuULBZFgbXAQdceGS4vNR\">\n                    \n                  </figure>\n                </li>\n              </ul>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                    <p>Both of these ways will work for any parallelogram. However, for some parallelograms the process of decomposing and rearranging requires a lot more steps than if we enclose the parallelogram with a rectangle and subtract the combined area of the two triangles in the corners.</p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26710\" data-record-model=\"ImageFile\"><img alt=\"A shaded parallelogram on a grid decomposed and rearranged into a rectangle.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/NyZhxEWPrDqwjbHsMhDiXbfA\">\n                      \n                    </figure>\n                  </div>\n                </div>\n              </div>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> of the parallelograms. For each figure that is <em>not</em> selected, explain how you know it is not a parallelogram. </p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29350\" data-record-model=\"ImageFile\"><img alt=\"5 figures labeled A, B, C, D, E.\" class=\"h-max-height--14-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/ESgSiRbMtJpvQv3vtmRou97b\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>Decompose and rearrange this parallelogram to make a rectangle.</p>\n                <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29351\" data-record-model=\"ImageFile\"><img alt=\"parallelogram on a grid. base = 9 units, height = 5 units. \" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/wp1rGBvvDmbJMWcgfyNc9Aak\">\n                  \n                </figure>\n              </li>\n              <li>\n                <p>What is the area of the parallelogram? Explain your reasoning.</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Find the area of the parallelogram.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29357\" data-record-model=\"ImageFile\"><img alt=\"A parallelogram with one side labeled 3.2 centimeters, and another side labeled 10 centimeters. A dashed line perpendicular to the 10 centimeter sides is labeled 3 centimeters\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/aqSHoFW7BkZEMSarTHTKiiKB\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Explain why this quadrilateral is <em>not</em> a parallelogram.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29353\" data-record-model=\"ImageFile\"><img alt=\"A quadrilateral on a grid.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/tyb9vPgCcgiJkUr21CeZ6xsR\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Find the area of each shape. Show your reasoning.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29345\" data-record-model=\"ImageFile\"><img alt=\"A shape with eight sides drawn on a grid.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/iSegiss6sqSUhL9iwodj6cf5\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29346\" data-record-model=\"ImageFile\"><img alt=\"A shape with six sides. It is 9 units long and six units wide at it’s widest point. Two vertical sides connect four sloped sides, which meet at either end of the shape.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/jyv4SaXG4RF7LqSgW7uSj8Vo\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 3.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Find the area of the rectangle with each set of side lengths.</p>\n            <ol>\n              <li>\n                <p>5 in and <span class=\"math math-repaired\" data-png-file-id=\"14\">\\(\\frac13\\)</span> in</p>\n              </li>\n              <li>\n                <p>5 in and <span class=\"math math-repaired\" data-png-file-id=\"3323\">\\(\\frac 43\\)</span> in</p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"13888\">\\(\\frac 52\\)</span> in and <span class=\"math math-repaired\" data-png-file-id=\"3323\">\\(\\frac 43\\)</span> in</p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"35327\">\\(\\frac 7 6\\)</span> in and <span class=\"math math-repaired\" data-png-file-id=\"35330\">\\(\\frac 67\\)</span> in</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 1.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l05","number":5,"title":"Bases and Heights of Parallelograms","introText":"Let’s investigate the area of parallelograms some more.","activities":[{"title":"5.1: A Parallelogram and Its Rectangles","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Elena and Tyler were finding the area of this parallelogram:</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27226\" data-record-model=\"ImageFile\"><img alt=\"shaded parallelogram on a grid. base = 7 units, height = 6 units.\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/32gBeU4rXrdLF2tRMQFUawnw\">\n                \n              </figure>\n              <p>Move the slider to see how Tyler did it:</p>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4263\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"\",\"height\":\"\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"showToolBar\":false,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4263-1\"></div>\n              </div>\n              <p>Move the slider to see how Elena did it:</p>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4264\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"\",\"height\":\"\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"showToolBar\":false,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4264-2\"></div>\n              </div>\n              <p>How are the two strategies for finding the area of a parallelogram the same? How they are different?</p>\n            </div>"},{"title":"5.2: The Right Height?","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Study the examples and non-examples of <strong>bases </strong>and <strong>heights</strong> of parallelograms.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                    <ul>\n                      <li>Examples: The dashed segments in these drawings represent the corresponding height for the given base.</li>\n                    </ul>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27230\" data-record-model=\"ImageFile\"><img alt=\"4 parallelograms with perpendicular heights provided\" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/wLTFHzrAXGsqPQRUfNcpAazD\">\n                      \n                    </figure>\n                  </div>\n                </div>\n                <div class=\"g--row g--row-2\">\n                  <div class=\"g--col-1 g--column g--content g--half g--row-2\">\n                    <ul>\n                      <li>Non-examples: The dashed segments in these drawings do <em>not</em> represent the corresponding height for the given base.</li>\n                    </ul>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--half g--row-2\">\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27231\" data-record-model=\"ImageFile\"><img alt=\"4 parallelograms where heights are not perpendicular to bases\" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/gHHJTH1Xbhm27kQPeQQNqYW1\">\n                      \n                    </figure>\n                  </div>\n                </div>\n              </div>\n              <ol>\n                <li>\n                  <p>Select <strong>all</strong> the statements that are true about bases and heights in a parallelogram.</p>\n                  <ol>\n                    <li>Only a horizontal side of a parallelogram can be a base.</li>\n                    <li>Any side of a parallelogram can be a base.</li>\n                    <li>A height can be drawn at any angle to the side chosen as the base.</li>\n                    <li>A base and its corresponding height must be perpendicular to each other.</li>\n                    <li>A height can only be drawn inside a parallelogram.</li>\n                    <li>A height can be drawn outside of the parallelogram, as long as it is drawn at a 90-degree angle to the base.</li>\n                    <li>A base cannot be extended to meet a height.</li>\n                  </ol>\n                </li>\n                <li>Five students labeled a base <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span> and a corresponding height <span class=\"math math-repaired\" data-png-file-id=\"55\">\\(h\\)</span> for each of these parallelograms. Are all drawings correctly labeled? Explain how you know.\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27232\" data-record-model=\"ImageFile\"><img alt=\"Five parallelograms labeled A--E.\" class=\"h-max-height--16-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/d4ZeVCTATB7F4uKeDevy3QRU\">\n                    \n                  </figure>\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>In the applet, the parallelogram is made of solid line segments, and the height and supporting lines are made of dashed line segments. A base b and corresponding height h are labeled.</p>\n                    \n                    <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4265\" data-record-model=\"GeogebraFile\">\n                      <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"658\",\"height\":\"612\",\"enableRightClick\":false,\"enableLabelDrags\":true,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"showToolBar\":false,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                      <div class=\"ggb-applet-container\" id=\"GeogebraFile-4265-3\"></div>\n                    </div>\n                    <p>Experiment with dragging all of the movable points around the screen. Can you change the parallelogram so that . . .</p>\n                    <p>its height is in a different location?</p>\n                    <p>it has horizontal sides?</p>\n                    <p>it is tall and skinny?</p>\n                    <p>it is also a rectangle?</p>\n                    <p>it is not a rectangle, and has b=5 and h=3?</p>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"5.3: Finding the Formula for Area of Parallelograms","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>For each parallelogram:</p>\n              <ul>\n                <li>Identify a base and a corresponding height, and record their lengths in the table.</li>\n                <li>Find the area of the parallelogram and record it in the last column of the table.</li>\n              </ul>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27233\" data-record-model=\"ImageFile\"><img alt=\"Four parallelograms A--D.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/XEeqob2iSoBbh6TEtxWniQfk\">\n                \n              </figure>\n              <table border=\"1\">\n                <tbody>\n                  <tr>\n                    <td><strong>parallelogram</strong></td>\n                    <td><strong>base (units)</strong></td>\n                    <td><strong>height (units)</strong></td>\n                    <td><strong>area (sq units)</strong></td>\n                  </tr>\n                  <tr>\n                    <td><strong>A</strong></td>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <td><strong>B</strong></td>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <td><strong>C</strong></td>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <td><strong>D</strong></td>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <td><strong>any parallelogram</strong></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"55\">\\(h\\)</span></td>\n                    <td></td>\n                  </tr>\n                </tbody>\n              </table>\n              <p>In the last row, write an expression for the area of any parallelogram, using <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"55\">\\(h\\)</span> .</p>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <ol>\n                      <li>What happens to the area of a parallelogram if the height doubles but the base is unchanged? If the height triples? If the height is 100 times the original?</li>\n                      <li>What happens to the area if both the base and the height double? Both triple? Both are 100 times their original lengths?\n                      </li>\n                    </ol>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ul>\n                <li>We can choose any of the four sides of a parallelogram as the <strong>base</strong>. Both the side (the segment) and its length (the measurement) are called the base.</li>\n                <li>\n                  <p>If we draw any perpendicular segment from a point on the base to the opposite side of the parallelogram, that segment will always have the same length. We call that value the <strong>height</strong>. There are infinitely many segments that can represent the height!</p>\n                </li>\n              </ul>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26711\" data-record-model=\"ImageFile\"><img alt=\"2 copies of the same parallelogram. \" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/33knwHKG6ctDyv9YehjKDww5\">\n                \n              </figure>\n              <p>Here are two copies of the same parallelogram. On the left, the side that is the base is 6 units long. Its corresponding height is 4 units. On the right, the side that is the base is 5 units long. Its corresponding height is 4.8 units. For both, three different segments are shown to represent the height. We could draw in many more!</p>\n              <p>No matter which side is chosen as the base, the area of the parallelogram is the product of that base and its corresponding height. We can check this:</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math math-repaired\">\\(4 \\times 6 = 24\\)</span></p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                    <p style=\"text-align:center\">and</p>\n                  </div>\n                  <div class=\"g--col-3 g--column g--content g--one-third g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math math-repaired\">\\(4.8 \\times 5 = 24\\)</span></p>\n                  </div>\n                </div>\n              </div>\n              <p>We can see why this is true by decomposing and rearranging the parallelograms into rectangles.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26712\" data-record-model=\"ImageFile\"><img alt=\"2 parallelograms, On left, base = 6, height = 4. On right, base = 5, height = 4 and 8 tenths.\" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/D5PLGAA6qn6vEvpuJNGFPrJs\">\n                \n              </figure>\n              <p>Notice that the side lengths of each rectangle are the base and height of the parallelogram. Even though the two rectangles have different side lengths, the products of the side lengths are equal, so they have the same area! And both rectangles have the same area as the parallelogram.</p>\n              <p>We often use letters to stand for numbers. If <span class=\"math math-repaired\">\\(b\\)</span> is base of a parallelogram (in units), and <span class=\"math math-repaired\">\\(h\\)</span> is the corresponding height (in units), then the area of the parallelogram (in square units) is the product of these two numbers. <span class=\"math math-displayed math-repaired\">\\(\\displaystyle b \\boldcdot h\\)</span></p>\n              <p>Notice that we write the multiplication symbol with a small dot instead of a <span class=\"math math-repaired\">\\(\\times\\)</span> symbol. This is so that we don’t get confused about whether <span class=\"math math-repaired\">\\(\\times\\)</span> means multiply, or whether the letter <span class=\"math math-repaired\">\\(x\\)</span> is standing in for a number.</p>\n              <p>In high school, you will be able to prove that a perpendicular segment from a point on one side of a parallelogram to the opposite side will always have the same length.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26713\" data-record-model=\"ImageFile\"><img alt=\"A parallelogram with five dashed perpendicular segments extending from the bottom of the parallelogram to the top. Each of the lines is labeled “h”.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/TsFVA1JiXJPE2cpf7dNetFzs\">\n                \n              </figure>\n              <p>You can see this most easily when you draw a parallelogram on graph paper. For now, we will just use this as a fact.</p>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> parallelograms that have a correct height labeled for the given base.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29359\" data-record-model=\"ImageFile\"><img alt=\"4 parallelograms on a grid, labeled A, B, C, D.\" class=\"h-max-height--13-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/gBbqFY5m9X7vukA14D4NaRaY\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>A</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>B</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>C</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>D</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>The side labeled <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span> has been chosen as the base for this parallelogram.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29360\" data-record-model=\"ImageFile\"><img alt=\"parallelogram on a grid. base = 4 units, distance from bottom side to top side = 2 units. Left and right sides are slanted.\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/k3qkKdiF6WMWj9qQhkK9BGRe\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--column g--two-third g--content g--col-2 g--row-1\">\n                  <p>Draw a segment showing the height corresponding to that base.</p>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Find the area of each parallelogram.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29362\" data-record-model=\"ImageFile\"><img alt=\"3 parallelograms on a grid, labeled A, B, C.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/foFfv3JuZoW1XShCTGovW3ch\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>If the side that is 6 units long is the base of this parallelogram, what is its corresponding height?</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29365\" data-record-model=\"ImageFile\"><img alt=\"Parallelogram. \" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/ZVeRetUqnXsD2oSscb6icyVH\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--column g--two-third g--content g--col-2 g--row-1\">\n                  \n                </div>\n              </div>\n            </div>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>6 units</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>4.8 units</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>4 units</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>5 units</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Find the area of each parallelogram.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29363\" data-record-model=\"ImageFile\"><img alt=\"3 parallelograms labeled A, B, C. \" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/tWaYddDfgxHuVywo2yGisFdo\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Do you agree with each of these statements? Explain your reasoning.</p>\n            <ol>\n              <li>A parallelogram has six sides.\n              </li>\n              <li>Opposite sides of a parallelogram are parallel.\n              </li>\n              <li>A parallelogram can have one pair or two pairs of parallel sides. \n              </li>\n              <li>All sides of a parallelogram have the same length.\n              </li>\n              <li>All angles of a parallelogram have the same measure. \n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 4.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>A square with an area of 1 square meter is decomposed into 9 identical small squares. Each small square is decomposed into two identical triangles.</p>\n            <ol>\n              <li>What is the area, in square meters, of 6 triangles? If you get stuck, consider drawing a diagram.\n              </li>\n              <li>How many triangles are needed to compose a region that is <span class=\"math math-repaired\" data-png-file-id=\"35329\">\\(1\\frac 12\\)</span> square meters?</li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 2.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l06","number":6,"title":"Area of Parallelograms","introText":"Let's practice finding the area of parallelograms.","activities":[{"title":"6.1: Missing Dots","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                    <div>\n                      <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27235\" data-record-model=\"ImageFile\"><img alt=\"An arrangement of dots.\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/3g11Xggk2EaNUGpRAuRWG3Kw\">\n                        \n                      </figure>\n                    </div>\n                  </div>\n                  <div class=\"g--column g--two-third g--content g--col-2 g--row-1\">\n                    <div>\n                      <p>How many dots are in the image?</p>\n                      <p>How do you see them?</p>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"6.2: More Areas of Parallelograms","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <ol>\n                    <li> \n                      \n                      <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4266\" data-record-model=\"GeogebraFile\">\n                        <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"\",\"height\":\"\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"showToolBar\":false,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                        <div class=\"ggb-applet-container\" id=\"GeogebraFile-4266-1\"></div>\n                      </div>\n                      <p>Calculate the area of the given figure in the applet. Then, check if your area calculation is correct by clicking the <em>Show Area</em> checkbox.</p>\n                    </li>\n                    <li>Uncheck the Area checkbox. Move one of the vertices of the parallelogram to create a new parallelogram. When you get a parallelogram that you like, sketch it and calculate the area. Then, check if your calculation is correct by using the <em>Show Area</em> button again.</li>\n                    <li>Repeat this process two more times. Draw and label each parallelogram with its measurements and the area you calculated.</li>\n                  </ol>\n                </li>\n                <li>Here is Parallelogram B. What is the corresponding height for the base that is 10 cm long? Explain or show your reasoning.\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27239\" data-record-model=\"ImageFile\"><img alt=\"A parallelogram with side lengths 15 centimeters and 10 centimeters. An 8-centimeter perpendicular segment connects one vertex of the 15-centimeter side to a point on the other 15-centimeter side.\" class=\"h-max-height--12-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/bKtakCCRXfdhesUP39J2r9Ki\">\n                    \n                  </figure>\n                </li>\n                <li>\n                  <p>Here are two different parallelograms with the same area.</p>\n                  \n                  <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4267\" data-record-model=\"GeogebraFile\">\n                    <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"\",\"height\":\"\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"showToolBar\":false,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                    <div class=\"ggb-applet-container\" id=\"GeogebraFile-4267-2\"></div>\n                  </div>\n                  <ol>\n                    <li>Explain why their areas are equal.</li>\n                    <li>Drag points to create two new parallelograms that are not identical copies of each other but that have the same area as each other. Sketch your parallelograms and explain or show how you know their areas are equal. Then, click on the <em>Check</em> button to see if the two areas are indeed equal.</li>\n                  </ol>\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Here is a parallelogram composed of smaller parallelograms. The shaded region is composed of four identical parallelograms. All lengths are in inches.</p>\n                    <div class=\"imgrid\">\n                      <div class=\"g--row g--row-1\">\n                        <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                          <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27240\" data-record-model=\"ImageFile\"><img alt=\"parallelogram composed of smaller parallelograms. The shaded region is composed of four identical parallelograms.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Rx9V97SHfwfMBwUWqonPHe3g\">\n                            \n                          </figure>\n                        </div>\n                        <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                          <p>What is the area of the unshaded parallelogram in the middle? Explain or show your reasoning.</p>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-video-link\" data-embedder-target=\"web\" data-record-id=\"146\" data-record-model=\"VideoLink\"><iframe allowfullscreen=\"true\" frameborder=\"0\" height=\"360\" mozillaallowfullscreen=\"true\" safariallowfullscreen=\"true\" src=\"https://player.vimeo.com/video/443559353\" width=\"640\"></iframe>\n                <figcaption class=\"c-figcaption\">Video <em>VLS G6U1V2 Parallelograms (Lessons 4–6)</em> available at <a href=\"https://player.vimeo.com/video/443559353\">https://player.vimeo.com/video/443559353</a>.</figcaption>\n              </figure>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Which three of these parallelograms have the same area as each other?</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29371\" data-record-model=\"ImageFile\"><img alt=\"Four parallelograms, labeled A, B, C, and D.\" class=\"h-max-height--14-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/KDP5kft6Bn3jGd78FknaHnFP\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>A</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>B</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>C</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>D</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Which pair of base and height produces the greatest area? All measurements are in centimeters.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(b = 4\\)</span>, <span class=\"math math-repaired\">\\(h=3.5\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(b = 0.8\\)</span>, <span class=\"math math-repaired\">\\(h=20\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(b = 6\\)</span>, <span class=\"math math-repaired\">\\(h=2.25\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(b = 10\\)</span>, <span class=\"math math-repaired\">\\(h=1.4\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Here are the areas of three parallelograms. Use them to find the missing length (labeled with a \"?\") on each parallelogram.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                  <p>A: 10 square units</p>\n                </div>\n                <div class=\"g--column g--one-third g--content g--col-2 g--row-1\">\n                  <p>B: 21 square units</p>\n                </div>\n                <div class=\"g--column g--one-third g--content g--col-3 g--row-1\">\n                  <p>C: 25 square units</p>\n                </div>\n              </div>\n            </div>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29370\" data-record-model=\"ImageFile\"><img alt=\"Three parallelograms labeled A, B, C.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/xzBKx2vm94wTD8JdQt1uG46d\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>The Dockland Building in Hamburg, Germany is shaped like a parallelogram.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29369\" data-record-model=\"ImageFile\"><img alt=\"A photograph of the Dockland Building in Hamburg, Germany. The building is shaped like a parallelogram.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/kYiQYtUeQZvPnawBV2c1BoD5\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  <p>If the length of the building is 86 meters and its height is 55 meters, what is the area of this face of the building?</p>\n                </div>\n              </div>\n            </div>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> segments that could represent a corresponding height if the side <span class=\"math math-repaired\" data-png-file-id=\"40\">\\(m\\)</span> is the base.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29367\" data-record-model=\"ImageFile\"><img alt=\"A parallelogram with a bottom side labeled m and a right side labeled n. Dashed lines e, f, j, and k are drawn perpendicular to side m, and dashed lines g and h are drawn perpendicular to side n.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/tFqfcBp8q4QSRV2SEENK4hVi\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>e</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>f</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>g</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>h</p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p>j</p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p>k</p>\n          </div>\n          <div class=\"im-c-content\">G: \n            <p>n</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 5.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Find the area of the shaded region. All measurements are in centimeters. Show your reasoning.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29341\" data-record-model=\"ImageFile\"><img alt=\"A shaded rectangle located at an angle within a larger rectangle. \" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/FHSqJnwV7jNK71sC9vXjDo9b\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 3.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l07","number":7,"title":"From Parallelograms to Triangles","introText":"Let’s compare parallelograms and triangles.","activities":[{"title":"7.1: Same Parallelograms, Different Bases","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here are two copies of a parallelogram. Each copy has one side labeled as the base <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span> and a segment drawn for its corresponding height and labeled <span class=\"math math-repaired\" data-png-file-id=\"55\">\\(h\\)</span>. </p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27245\" data-record-model=\"ImageFile\"><img alt=\"2 triangles, base b, height h. On right, b is slanted side and height is outside of triangle, perpendicular to the slanted side\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/o4g5vFvncAUBVU5bJX2cMKkb\">\n                \n              </figure>\n              <ol>\n                <li>The base of the parallelogram on the left is 2.4 centimeters; its corresponding height is 1 centimeter. Find its area in square centimeters.\n                </li>\n                <li>The height of the parallelogram on the right is 2 centimeters. How long is the base of that parallelogram? Explain your reasoning.\n                </li>\n              </ol>\n            </div>"},{"title":"7.2: A Tale of Two Triangles (Part 1)","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Two polygons are identical if they match up exactly when placed one on top of the other.</p>\n              <ol>\n                <li>Draw <em>one</em> line to decompose each polygon into two identical triangles, if possible. If you choose to, you can also draw the triangles. \n                  <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4268\" data-record-model=\"GeogebraFile\">\n                    <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"undefined\",\"height\":\"undefined\",\"enableRightClick\":true,\"enableLabelDrags\":true,\"showAlgebraInput\":true,\"showResetIcon\":true,\"enableShiftDragZoom\":true,\"showMenuBar\":true,\"showToolBar\":true,\"allowStyleBar\":true,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                    <div class=\"ggb-applet-container\" id=\"GeogebraFile-4268-1\"></div>\n                  </div>\n                </li>\n                <li>\n                  <p>Which quadrilaterals can be decomposed into two identical triangles?</p>\n                  <p>Pause here for a small-group discussion.</p>\n                </li>\n                <li>\n                  <p>Study the quadrilaterals that were, in fact, decomposable into two identical triangles. What do you notice about them? Write a couple of observations about what these quadrilaterals have in common.</p>\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Draw some other types of quadrilaterals that are not already shown. Try to decompose them into two identical triangles. Can you do it? Come up with a general rule about what must be true if a quadrilateral can be decomposed into two identical triangles.</p>\n                    <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"5468\" data-record-model=\"GeogebraFile\">\n                      <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"522\",\"height\":\"515\",\"enableRightClick\":true,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"showToolBar\":true,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                      <div class=\"ggb-applet-container\" id=\"GeogebraFile-5468-2\"></div>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"7.3: A Tale of Two Triangles (Part 2)","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>This applet has eight pairs of triangles. Each group member should choose 1–2 pairs of triangles. Use them to help you answer the following questions.</p>\n              <ol>\n                <li>\n                  <ol>\n                    <li>\n                      <p>Which pair(s) of triangles do you have?</p>\n                    </li>\n                    <li>\n                      <p>Can each pair be composed into a rectangle? A parallelogram?</p>\n                    </li>\n                  </ol>\n                </li>\n                <li>Discuss your responses to the first question with your group. Then, complete each of the following statements with <em>all</em>, <em>some</em>, or <em>none</em>. Sketch 1–2 examples to illustrate each completed statement.\n                  <ol>\n                    <li>\n                      <p>________________ of these pairs of identical triangles can be composed into a <em>rectangle</em>.</p>\n                    </li>\n                    <li>________________ of these pairs of identical triangles can be composed into a <em>parallelogram</em>.</li>\n                  </ol>\n                </li>\n              </ol>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4269\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"\",\"height\":\"\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"showToolBar\":false,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4269-3\"></div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>A parallelogram can always be decomposed into two identical triangles by a segment that connects opposite vertices.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26717\" data-record-model=\"ImageFile\"><img alt=\"Three parallelograms showing decompositions into two identical triangles.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/MttjdeCJGh5JvK3pwg7ZBBdm\">\n                \n              </figure>\n              <p>Going the other way around, two identical copies of a triangle can always be arranged to form a parallelogram, regardless of the type of triangle being used.</p>\n              <p>To produce a parallelogram, we can join a triangle and its copy along any of the three sides, so the same pair of triangles can make different parallelograms.</p>\n              <p>Here are examples of how two copies of both Triangle A and Triangle F can be composed into three different parallelograms.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26718\" data-record-model=\"ImageFile\"><img alt=\"Six parallelograms composed from two identical triangles.\" class=\"h-max-height--16-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/ftqpCE5vXPxKEQfwTsA5Ynfy\">\n                \n              </figure>\n              <p>This special relationship between triangles and parallelograms can help us reason about the area of any triangle.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </main>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <p>To decompose a quadrilateral into two identical shapes, Clare drew a dashed line as shown in the diagram.</p>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29374\" data-record-model=\"ImageFile\"><img alt=\"Trapezoid base 1, 6 units, base 2, 2 units, height 4 units.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/KzBGN8Px8at5Lvees9j5RBBX\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n            <ol>\n              <li>\n                <p>She said the that two resulting shapes have the same area. Do you agree? Explain your reasoning.</p>\n              </li>\n              <li>\n                <p>Did Clare partition the figure into two identical shapes? Explain your reasoning.</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Triangle R is a right triangle. Can we use two copies of Triangle R to compose a parallelogram that is not a square?</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29376\" data-record-model=\"ImageFile\"><img alt=\"2 identical triangles labeled R\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/FpYzLvDFcV8sAVwXZGPrraZp\">\n              \n            </figure>\n            <p>If so, explain how or sketch a solution. If not, explain why not.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Two copies of this triangle are used to compose a parallelogram. Which parallelogram <em>cannot</em> be a result of the composition? If you get stuck, consider using tracing paper.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29379\" data-record-model=\"ImageFile\"><img alt=\"A three sided figure in a grid. Vertices located at two units right, 1 unit up; 7 units right, 2 units up; and 1 unit right, 3 units up.\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/VmjzaFPtL3B9MDRKts6bcxN4\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--row-1 g--two-third\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29380\" data-record-model=\"ImageFile\"><img alt=\"Four parallelograms labeled A, B, C, and D.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Gt95bSgxHEEJGwNXNBLCM9o9\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>A</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>B</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>C</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>D</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>On the grid, draw at least three different quadrilaterals that can each be decomposed into two identical triangles with a single cut (show the cut line). One or more of the quadrilaterals should have non-right angles.</p>\n                <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27247\" data-record-model=\"ImageFile\"><img alt=\"Image of a grid.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vupNoA5g96AkAtsSrCipKyG6\">\n                  \n                </figure>\n              </li>\n              <li>Identify the type of each quadrilateral.</li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>A parallelogram has a base of 9 units and a corresponding height of <span class=\"math math-repaired\" data-png-file-id=\"781\">\\(\\frac23\\)</span> units. What is its area?</p>\n              </li>\n              <li>\n                <p>A parallelogram has a base of 9 units and an area of 12 square units. What is the corresponding height for that base?</p>\n              </li>\n              <li>\n                <p>A parallelogram has an area of 7 square units. If the height that corresponds to a base is <span class=\"math math-repaired\" data-png-file-id=\"15\">\\(\\frac14\\)</span> unit, what is the base?</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 6.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the segments that could represent the height if side <span class=\"math math-repaired\" data-png-file-id=\"749\">\\(n\\)</span> is the base.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29367\" data-record-model=\"ImageFile\"><img alt=\"A parallelogram with a bottom side labeled m and a right side labeled n. Dashed lines e, f, j, and k are drawn perpendicular to side m, and dashed lines g and h are drawn perpendicular to side n.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/tFqfcBp8q4QSRV2SEENK4hVi\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(e\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(f\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(g\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(h\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(m\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p><span class=\"math math-repaired\">\\(n\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">G: \n            <p><span class=\"math math-repaired\">\\(j\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">H: \n            <p><span class=\"math math-repaired\">\\(k\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 5.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l08","number":8,"title":"Area of Triangles","introText":"Let’s use what we know about parallelograms to find the area of triangles.","activities":[{"title":"8.1: Composing Parallelograms","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here is Triangle M.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27258\" data-record-model=\"ImageFile\"><img alt=\"A triangle labeled “M”. The left side is 4 units tall and the top side is 6 units wide.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/4n1r1dA7beQkDTy9D6W2CfiU\">\n                \n              </figure>\n              <p>Han made a copy of Triangle M and composed three different parallelograms using the original M and the copy, as shown here.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27259\" data-record-model=\"ImageFile\"><img alt=\"3 different parallelograms on a grid composed of Triangle M and a copy.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/NiGnuhvn2rTprTttXkLEjiaE\">\n                \n              </figure>\n              <ol>\n                <li>\n                  <p>For each parallelogram Han composed, identify a base and a corresponding height, and write the measurements on the drawing.</p>\n                </li>\n                <li>Find the area of each parallelogram Han composed. Show your reasoning.\n                </li>\n              </ol>\n            </div>"},{"title":"8.2: More Triangles","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Find the areas of at least two of these triangles. Show your reasoning.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27262\" data-record-model=\"ImageFile\"><img alt=\"Four triangles on a grid labeled A--D.\" class=\"h-max-height--24-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/6HVJghBHZp32GjLMrn9ZAQaY\">\n                \n              </figure>\n              \n            </div>"},{"title":"8.3: Decomposing a Parallelogram","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Your teacher will give you two copies of a parallelogram. Glue or tape <em>one</em> copy of your parallelogram here and find its area. Show your reasoning.</p>\n                </li>\n                <li>\n                  <p>Decompose the second copy of your parallelogram by cutting along the dotted lines. Take <em>only</em> the small triangle and the trapezoid, and rearrange these two pieces into a different parallelogram. Glue or tape the newly composed parallelogram on your paper.</p>\n                </li>\n                <li>Find the area of the new parallelogram you composed. Show your reasoning.\n                </li>\n                <li>What do you notice about the relationship between the area of this new parallelogram and the original one?\n                </li>\n                <li>How do you think the area of the large triangle compares to that of the new parallelogram: Is it larger, the same, or smaller? Why is that?\n                </li>\n                <li>\n                  <p>Glue or tape the remaining large triangle to your paper. Use any part of your work to help you find its area. Show your reasoning.</p>\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Can you decompose this triangle and rearrange its parts to form a rectangle? Describe how it could be done.</p>\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27268\" data-record-model=\"ImageFile\"><img alt=\"Triangle \" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/pCNUBMaJP61Q5ncYyrm1pjia\">\n                      \n                    </figure>\n                    \n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>We can reason about the area of a triangle by using what we know about parallelograms. Here are three general ways to do this:</p>\n              <ul>\n                <li>\n                  <p>Make a copy of the triangle and join the original and the copy along an edge to create a parallelogram. Because the two triangles have the same area, one copy of the triangle has half the area of that parallelogram.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26719\" data-record-model=\"ImageFile\"><img alt=\"Four figures labeled A, B, C, and D.\" class=\"h-max-height--16-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Jpt1g5zX6wofDoEEhnmxgrXH\">\n                    \n                  </figure>\n                  <p>The area of Parallelogram B is 16 square units because the base is 8 units and the height 2 units. The area of Triangle A is half of that, which is 8 square units. The area of Parallelogram D is 24 square units because the base is 4 units and the height 6 units. The area of Triangle C is half of that, which is 12 square units.</p>\n                </li>\n              </ul>\n              <ul>\n                <li>\n                  <p>Decompose the triangle into smaller pieces and compose them into a parallelogram.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26720\" data-record-model=\"ImageFile\"><img alt=\"Two images of a triangle. \" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/xpUJrhSqvv7sCXUkqPkkScoN\">\n                    \n                  </figure>\n                  <p>In the new parallelogram, <span class=\"math math-repaired\">\\(b = 6\\)</span>, <span class=\"math math-repaired\">\\(h = 2\\)</span>, and <span class=\"math math-repaired\">\\(6 \\boldcdot 2 = 12\\)</span>, so its area is 12 square units. Because the original triangle and the parallelogram are composed of the same parts, the area of the original triangle is also 12 square units.</p>\n                </li>\n              </ul>\n              <ul>\n                <li>\n                  <p>Draw a rectangle around the triangle. Sometimes the triangle has half of the area of the rectangle.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26721\" data-record-model=\"ImageFile\"><img alt=\"Triangle drawn 3 times on grid. Base = 6, height = 3. In middle rectangle drawn around triangle. On right height drawn.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/59VL8YP46Q1YSCGRwcA2qgGN\">\n                    \n                  </figure>\n                  <p>The large rectangle can be decomposed into smaller rectangles. The one on the left has area <span class=\"math math-repaired\">\\(4 \\boldcdot 3\\)</span> or 12 square units; the one on the right has area <span class=\"math math-repaired\">\\(2 \\boldcdot 3\\)</span> or 6 square units. The large triangle is also decomposed into two right triangles. Each of the right triangles is half of a smaller rectangle, so their areas are 6 square units and 3 square units. The large triangle has area 9 square units.</p>\n                  <p>Sometimes, the triangle is half of what is left of the rectangle after removing two copies of the smaller right triangles.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26722\" data-record-model=\"ImageFile\"><img alt=\"Three images of the same triangle.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/KWBrP3eiCmrg7NyP6rWMcFJf\">\n                    \n                  </figure>\n                  <p>The right triangles being removed can be composed into a small rectangle with area <span class=\"math math-repaired\">\\((2 \\boldcdot 3)\\)</span> square units. What is left is a parallelogram with area <span class=\"math math-repaired\">\\(5 \\boldcdot 3 - 2 \\boldcdot 3\\)</span>, which equals <span class=\"math math-repaired\">\\(15-6\\)</span> or 9 square units. Notice that we can compose the same parallelogram with two copies of the original triangle! The original triangle is half of the parallelogram, so its area is <span class=\"math math-repaired\">\\( \\frac12 \\boldcdot 9\\)</span> or 4.5 square units.</p>\n                </li>\n              </ul>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </main>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>To find the area of this right triangle, Diego and Jada used different strategies. Diego drew a line through the midpoints of the two longer sides, which decomposes the triangle into a trapezoid and a smaller triangle. He then rearranged the two shapes into a parallelogram.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29385\" data-record-model=\"ImageFile\"><img alt=\"A triangle decomposed into a trapezoid and a smaller triangle, then rearranged into a parallelogram. \" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/J8FJmTvn5p8DTtjznVbafeXL\">\n              \n            </figure>\n            <p>Jada made a copy of the triangle, rotated it, and lined it up against one side of the original triangle so that the two triangles make a parallelogram.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29386\" data-record-model=\"ImageFile\"><img alt=\"A triangle with one side labeled 3 feet and another labeled 8 ft. To the left is the same triangle with a copy composed along the 8 feet side to create a parallelogram.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/1Q4TkpJYtAVdPYiP2c8UMT8A\">\n              \n            </figure>\n            <ol>\n              <li>Explain how Diego might use his parallelogram to find the area of the triangle.\n              </li>\n              <li>Explain how Jada might use her parallelogram to find the area of the triangle.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Find the area of the triangle. Explain or show your reasoning.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                  <p>a. </p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29382\" data-record-model=\"ImageFile\"><img alt=\"triangle on a grid, base = 6 units, height = 4 units.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/GqD83JC9VNorUeXaKTF51E2o\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                  <p>b. </p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29383\" data-record-model=\"ImageFile\"><img alt=\"Triangle on grid, base 4, height 3 units.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Y3FD4EteZ2eoiopmBaVDuF7s\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Which of the three triangles has the greatest area? Show your reasoning. If you get stuck, try using what you know about the area of parallelograms.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29389\" data-record-model=\"ImageFile\"><img alt=\"Three triangles labeled A, B, and C. Triangle A is a right triangle with a base of 5 and a height of 4. Triangle B has a base of 4 and a height of 5. Triangle C has a base of 4 and a height of 5.\" class=\"h-max-height--12-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/aTmHuSfaFgCDdDMHatpMBXTH\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Draw an identical copy of each triangle such that the two copies together form a parallelogram. If you get stuck, consider using tracing paper.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29377\" data-record-model=\"ImageFile\"><img alt=\"Three triangles labeled D, E, and F.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/VE8UhwU2Ty31oAiAXpX7GNuu\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 7.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>A parallelogram has a base of 3.5 units and a corresponding height of 2 units. What is its area?</p>\n              </li>\n              <li>\n                <p>A parallelogram has a base of 3 units and an area of 1.8 square units. What is the corresponding height for that base?</p>\n              </li>\n              <li>\n                <p>A parallelogram has an area of 20.4 square units. If the height that corresponds to a base is 4 units, what is the base?</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 6.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l09","number":9,"title":"Formula for the Area of a Triangle","introText":"Let’s write and use a formula to find the area of a triangle.","activities":[{"title":"9.1: Bases and Heights of a Triangle","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Study the examples and non-examples of <strong>bases</strong> and <strong>heights</strong> in a triangle.</p>\n              <ul>\n                <li>Examples: These dashed segments represent heights of the triangle.</li>\n              </ul>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27275\" data-record-model=\"ImageFile\"><img alt=\"Three copies of a triangle. Each copy shows a different base and height pair.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/N6paAWBBNrommKBSpP8KD5Cm\">\n                \n              </figure>\n              <ul>\n                <li>Non-examples: These dashed segments do <em>not</em> represent heights of the triangle.</li>\n              </ul>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27276\" data-record-model=\"ImageFile\"><img alt=\"Three copies of a triangle. Each copy has a different side labeled base and a line from the base that is not the height.\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/CYWk8fUzehnEtYuTawQAqwW2\">\n                \n              </figure>\n              <p>Select <strong>all</strong> the statements that are true about bases and heights in a triangle.</p>\n              <ol>\n                <li>Any side of a triangle can be a base.</li>\n                <li>There is only one possible height.</li>\n                <li>A height is always one of the sides of a triangle.</li>\n                <li>A height that corresponds to a base must be drawn at an acute angle to the base.</li>\n                <li>A height that corresponds to a base must be drawn at a right angle to the base.</li>\n                <li>Once we choose a base, there is only one segment that represents the corresponding height.</li>\n                <li>A segment representing a height must go through a vertex.</li>\n              </ol>\n            </div>"},{"title":"9.2: Finding a Formula for Area of a Triangle","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>For each triangle:</p>\n              <ul>\n                <li>Identify a base and a corresponding height, and record their lengths in the table.</li>\n                <li>Find the area of the triangle and record it in the last column of the table.</li>\n              </ul>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27278\" data-record-model=\"ImageFile\"><img alt=\"Four triangles labeled A--D on a grid.\" class=\"h-max-height--19-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/uHPxFXJw1XaQ31WjcvpG3RTe\">\n                \n              </figure>\n              <table border=\"1\" cellpadding=\"1\" cellspacing=\"1\">\n                <thead>\n                  <tr>\n                    <th scope=\"col\">triangle</th>\n                    <th scope=\"col\">base (units)</th>\n                    <th scope=\"col\">height (units)</th>\n                    <th scope=\"col\">area (square units)</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr>\n                    <td><strong>A</strong></td>\n                    <td> </td>\n                    <td> </td>\n                    <td> </td>\n                  </tr>\n                  <tr>\n                    <td><strong>B</strong></td>\n                    <td> </td>\n                    <td> </td>\n                    <td> </td>\n                  </tr>\n                  <tr>\n                    <td><strong>C</strong></td>\n                    <td> </td>\n                    <td> </td>\n                    <td> </td>\n                  </tr>\n                  <tr>\n                    <td><strong>D</strong></td>\n                    <td> </td>\n                    <td> </td>\n                    <td> </td>\n                  </tr>\n                  <tr>\n                    <td><strong>any triangle</strong></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"55\">\\(h\\)</span></td>\n                    <td> </td>\n                  </tr>\n                </tbody>\n              </table>\n              <p>In the last row, write an expression for the area of any triangle, using <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"55\">\\(h\\)</span>.</p>\n            </div>"},{"title":"9.3: Applying the Formula for Area of Triangles","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>For each triangle, circle a base measurement that you can use to find the area of the triangle. Then, find the area of any <em>three</em> triangles. Show your reasoning.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27279\" data-record-model=\"ImageFile\"><img alt=\"Five triangles, labeled A, B, C, D, and E.\" class=\"h-max-height--20-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/o56HaAzTszpmW8oLNxHkSZYj\">\n                \n              </figure>\n              \n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ul>\n                <li>We can choose any of the three sides of a triangle to call the <strong>base</strong>. The term “base” refers to both the side and its length (the measurement).</li>\n                <li>The corresponding <strong>height</strong> is the length of a perpendicular segment from the base to the vertex opposite of it. The <strong>opposite vertex</strong> is the vertex that is <em>not</em> an endpoint of the base.</li>\n              </ul>\n              <p>Here are three pairs of bases and heights for the same triangle. The dashed segments in the diagrams represent heights.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26723\" data-record-model=\"ImageFile\"><img alt=\"Three images of a triangle, each with a different side labeled “base” and an accompanying dashed line perpendicular to the base indicating the height.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/AfFLrVQTvvcMt7Z7mBRM5xow\">\n                \n              </figure>\n              <p>A segment showing a height must be drawn at a right angle to the base, but it can be drawn in more than one place. It does not have to go through the opposite vertex, as long as it connects the base and a line that is parallel to the base and goes through the opposite vertex, as shown here.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26724\" data-record-model=\"ImageFile\"><img alt=\"Triangle with 3 perpendicular heights drawn\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/iDUAMpA1Ehxvfb5dEiobR1L4\">\n                \n              </figure>\n              <p>The base-height pairs in a triangle are closely related to those in a parallelogram. Recall that two copies of a triangle can be composed into one or more parallelograms. Each parallelogram shares at least one base with the triangle.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26725\" data-record-model=\"ImageFile\"><img alt=\"Two identical triangles, each with a copy composing the triangle into two different parallelograms.\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/bM2ZBgXrAy2EMSTwJPbt8RbQ\">\n                \n              </figure>\n              <p>For any base that they share, the corresponding height is also shared, as shown by the dashed segments.</p>\n              <p>We can use the base-height measurements and our knowledge of parallelograms to find the area of any triangle.</p>\n              <ul>\n                <li>The formula for the area of a parallelogram with base <span class=\"math math-repaired\">\\(b\\)</span> and height <span class=\"math math-repaired\">\\(h\\)</span> is <span class=\"math math-repaired\">\\(b \\boldcdot h\\)</span>.</li>\n                <li>A triangle takes up half of the area of a parallelogram with the same base and height. We can therefore express the area <span class=\"math math-repaired\">\\(A\\)</span> of a triangle as: <span class=\"math math-displayed math-repaired\">\\(\\displaystyle A = \\frac12 \\boldcdot b \\boldcdot h\\)</span>\n                </li>\n              </ul>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26726\" data-record-model=\"ImageFile\"><img alt=\"Three figures: triangle A with base 5 and height 6; triangle B with base 3 and height 3; triangle C with base 12 and height 4.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/C3H5vBH4gK4Aw8h4ffcY6bf2\">\n                \n              </figure>\n              <ul>\n                <li>\n                  <p>The area of Triangle A is 15 square units because <span class=\"math math-repaired\">\\(\\frac12 \\boldcdot 5 \\boldcdot 6=15\\)</span>.</p>\n                </li>\n                <li>\n                  <p>The area of Triangle B is 4.5 square units because <span class=\"math math-repaired\">\\(\\frac12 \\boldcdot 3 \\boldcdot 3 = 4.5\\)</span>. </p>\n                </li>\n                <li>\n                  <p>The area of Triangle C is 24 square units because <span class=\"math math-repaired\">\\(\\frac12 \\boldcdot 12 \\boldcdot 4 = 24\\)</span>.</p>\n                </li>\n              </ul>\n              <p>In each case, one side of the triangle is the base but neither of the other sides is the height. This is because the angle between them is not a right angle.  </p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                    <p>In right triangles, however, the two sides that are perpendicular can be a base and a height.</p>\n                    <p>The area of this triangle is 18 square units whether we use 4 units or 9 units for the base.</p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26727\" data-record-model=\"ImageFile\"><img alt=\"A right triangle with legs of length 4 and 9.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Aaqvz1EzxebpomTkJtFMgmsA\">\n                      \n                    </figure>\n                  </div>\n                </div>\n              </div>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> drawings in which a corresponding height <span class=\"math math-repaired\" data-png-file-id=\"55\">\\(h\\)</span> for a given base <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span> is correctly identified.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29394\" data-record-model=\"ImageFile\"><img alt=\"Six images of the same triangle, labeled A, B, C, D, E, and F.\" class=\"h-max-height--12-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/viXKWZAripWNthcHL6usijra\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>A</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>B</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>C</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>D</p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p>E</p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p>F</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>For each triangle, a base and its corresponding height are labeled.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29390\" data-record-model=\"ImageFile\"><img alt=\"3 triangles on a grid labeled A, B, C.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Z64hVsLN72bZuUKs2NfEeb7F\">\n              \n            </figure>\n            <ol>\n              <li>Find the area of each triangle.\n              </li>\n              <li>How is the area related to the base and its corresponding height?\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Here is a right triangle. Name a corresponding height for each base.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29395\" data-record-model=\"ImageFile\"><img alt=\"A triangle with sides labeled d, e, and f. The angle opposite side D is a right angle. A segment labeled g is perpendicular to side d and extends to the opposite vertex.\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/prUqTf2JuReKCiXBRShyzV6e\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--column g--two-third g--content g--col-2 g--row-1\">\n                  <ol>\n                    <li>Side <span class=\"math math-repaired\" data-png-file-id=\"292\">\\(d\\)</span>\n                    </li>\n                    <li>Side <span class=\"math math-repaired\" data-png-file-id=\"108\">\\(e\\)</span>\n                    </li>\n                    <li>Side <span class=\"math math-repaired\" data-png-file-id=\"25\">\\(f\\)</span>\n                    </li>\n                  </ol>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Find the area of the shaded triangle. Show your reasoning.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29388\" data-record-model=\"ImageFile\"><img alt=\"A square with a shaded triangle contained inside it.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/JsgTKPRX8zV8busX41PuLbDi\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 8.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Andre drew a line connecting two opposite corners of a parallelogram. Select <strong>all</strong> true statements about the triangles created by the line Andre drew.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29381\" data-record-model=\"ImageFile\"><img alt=\"A parallelogram with a line connecting two opposite corners. The parallelogram has a base of 3 units and a height of 9 units.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/xXfY5euaJjeh1hC5DtHDSG2L\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>Each triangle has two sides that are 3 units long.</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>Each triangle has a side that is the same length as the diagonal line.</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>Each triangle has one side that is 3 units long.</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>When one triangle is placed on top of the other and their sides are aligned, we will see that one triangle is larger than the other.</p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p>The two triangles have the same area as each other.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 7.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Here is an octagon. (Note: The diagonal sides of the octagon are <em>not</em> 4 inches long.)</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--five-twelfth g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29348\" data-record-model=\"ImageFile\"><img alt=\"An octagon with straight sides that are 4 inches long, and angled sides that are both 3 inches high and 3 inches wide.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/zxUi5h8yjPKipFPjeDKPyN5U\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--row-1 g--seven-twelfth\">\n                  <ol>\n                    <li>While estimating the area of the octagon, Lin reasoned that it must be less than 100 square inches. Do you agree? Explain your reasoning.\n                    </li>\n                    <li>Find the exact area of the octagon. Show your reasoning.</li>\n                  </ol>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 3.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l10","number":10,"title":"Bases and Heights of Triangles","introText":"Let’s use different base-height pairs to find the area of a triangle.","activities":[{"title":"10.1: An Area of 12","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Draw one triangle with an area of 12 square units. Try to draw a non-right triangle. Be prepared to explain how you know the area of your triangle is 12 square units.</p>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4270\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"\",\"height\":\"\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"showToolBar\":true,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4270-1\"></div>\n              </div>\n            </div>"},{"title":"10.2: Hunting for Heights","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Here are three copies of the same triangle. The triangle is rotated so that the side chosen as the base is at the bottom and is horizontal. Draw a height that corresponds to each base. Use an index card to help you.</p>\n                  <div class=\"imgrid\">\n                    <div class=\"g--row g--row-1\">\n                      <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                        <p>Side <span class=\"math math-repaired\" data-png-file-id=\"81\">\\(a\\)</span> as the base:</p>\n                        <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27286\" data-record-model=\"ImageFile\"><img alt=\"A triangle with sides labeled a, b, and c.\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/C61M1XJ7jiJWGnMr96C1RaHG\">\n                          \n                        </figure>\n                      </div>\n                      <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                        <p>Side <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span> as the base:</p>\n                        <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27287\" data-record-model=\"ImageFile\"><img alt=\"A triangle with sides labeled a, b, and c.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/axaDhy1EjbKDj5JG9ALr61tC\">\n                          \n                        </figure>\n                      </div>\n                    </div>\n                    <div class=\"g--row g--row-2\">\n                      <div class=\"g--col-1 g--column g--content g--half g--row-2\">\n                        <p>Side <span class=\"math math-repaired\" data-png-file-id=\"98\">\\(c\\)</span> as the base:</p>\n                        <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27288\" data-record-model=\"ImageFile\"><img alt=\"A triangle with sides labeled a, b, and c.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/5fZxp7ifpPFcEPJ3SKRWyEMy\">\n                          \n                        </figure>\n                      </div>\n                      <div class=\"g--col-2 g--column g--content g--half g--row-2\">\n                        \n                        <p>Pause for your teacher’s instructions before moving to the next question.</p>\n                      </div>\n                    </div>\n                  </div>\n                </li>\n                <li>\n                  <p>Draw a line segment to show the height for the chosen base in each triangle.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27289\" data-record-model=\"ImageFile\"><img alt=\"Six triangles labeled A--F each with one side marked as the base.\" class=\"h-max-height--14-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/buZopEibb2K37tnERUNs4uCL\">\n                    \n                  </figure>\n                </li>\n              </ol>\n            </div>"},{"title":"10.3: Some Bases Are Better Than Others","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>For each triangle, identify and label a base and height. If needed, draw a line segment to show the height.</p>\n              <p>Then, find the area of the triangle. Show your reasoning. (The side length of each square on the grid is 1 unit.)</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27293\" data-record-model=\"ImageFile\"><img alt=\"Four triangles labeled A--D on a grid.\" class=\"h-max-height--16-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/TLfQKaT86J9jBQwHGKc1MTNh\">\n                \n              </figure>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Find the area of this triangle. Show your reasoning.</p>\n                    <div>\n                      <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27292\" data-record-model=\"ImageFile\"><img alt=\"A triangle on a grid.\" class=\"h-max-height--14-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/R6wNr7ok8NaMrrrPLpWUvdBo\">\n                        \n                      </figure>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-video-link\" data-embedder-target=\"web\" data-record-id=\"147\" data-record-model=\"VideoLink\"><iframe allowfullscreen=\"true\" frameborder=\"0\" height=\"360\" mozillaallowfullscreen=\"true\" safariallowfullscreen=\"true\" src=\"https://player.vimeo.com/video/443857237\" width=\"640\"></iframe>\n                <figcaption class=\"c-figcaption\">Video <em>VLS G6U1V3 Triangles (Lessons 7–10)</em> available at <a href=\"https://player.vimeo.com/video/443857237\">https://player.vimeo.com/video/443857237</a>.</figcaption>\n              </figure>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>For each triangle, a base is labeled <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span>. Draw a line segment that shows its corresponding height. Use an index card to help you draw a straight line.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29398\" data-record-model=\"ImageFile\"><img alt=\"3 triangles with 1 side on each labeled b.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/e7XsZDTn9zvbgdYwBN6WFXx5\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Select all triangles that have an area of 8 square units. Explain how you know.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29399\" data-record-model=\"ImageFile\"><img alt=\"5 triangles on grid labeled A, B, C, D, E.\" class=\"h-max-height--12-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/XZJAmPFrvQ59CDRFsg1U4Xfx\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Find the area of the triangle. Show your reasoning.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29400\" data-record-model=\"ImageFile\"><img alt=\"Triangle on grid, base = 6, height = 4\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/UUQo1fWRMutt4tJgvKxPbUbr\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  <p>If you get stuck, carefully consider which side of the triangle to use as the base.</p>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Can side <span class=\"math math-repaired\" data-png-file-id=\"292\">\\(d\\)</span> be the base for this triangle? If so, which length would be the corresponding height? If not, explain why not.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29395\" data-record-model=\"ImageFile\"><img alt=\"A triangle with sides labeled d, e, and f. The angle opposite side D is a right angle. A segment labeled g is perpendicular to side d and extends to the opposite vertex.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/prUqTf2JuReKCiXBRShyzV6e\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Find the area of this shape. Show your reasoning.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29343\" data-record-model=\"ImageFile\"><img alt=\"A shape with six sides. There are two vertical sides measuring five units, two angled sides that fall 2 units over 4 units and two sides that fall 2 units over 2 units.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/2YXc9UpF9MyRVaLHULxCRLAZ\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 3.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>On the grid, sketch two different parallelograms that have equal area. Label a base and height of each and explain how you know the areas are the same.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27247\" data-record-model=\"ImageFile\"><img alt=\"Image of a grid.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vupNoA5g96AkAtsSrCipKyG6\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 6.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l11","number":11,"title":"Polygons","introText":"Let’s investigate polygons and their areas.","activities":[{"title":"11.1: Which One Doesn’t Belong: Bases and Heights","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Which one doesn't belong?</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27298\" data-record-model=\"ImageFile\"><img alt=\"Four triangles on a grid, labeled S, T, U, and V.\" class=\"h-max-height--15-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/KpYLFhV9dgsS2Mm2TM4vESA6\">\n                \n              </figure>\n              \n            </div>"},{"title":"11.2: What Are Polygons?","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here are five <strong>polygons</strong>:</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27299\" data-record-model=\"ImageFile\"><img alt=\"5 polygons\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/VoF994PnXWy2GWoLpQZyfAkV\">\n                \n              </figure>\n              <p>Here are six figures that are <em>not</em> polygons:</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27300\" data-record-model=\"ImageFile\"><img alt=\" six figures that are not polygons:\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/BxMSkSsKxy6G9WdgZsHuj9FD\">\n                \n              </figure>\n              \n              <ol>\n                <li>\n                  <p>Circle the figures that are polygons.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26731\" data-record-model=\"ImageFile\"><img alt=\"Ten figures labeled A--J.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/WP3T1Zrray7GcTKoEL6Vfobd\">\n                    \n                  </figure>\n                </li>\n                <li>\n                  <p>What do the figures you circled have in common? What characteristics helped you decide whether a figure was a polygon?</p>\n                </li>\n              </ol>\n            </div>"},{"title":"11.3: Quadrilateral Strategies","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Find the area of <em>two</em> <strong>quadrilaterals</strong> of your choice. Show your reasoning.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27305\" data-record-model=\"ImageFile\"><img alt=\"Six quadrilaterals labeled A--F.\" class=\"h-max-height--16-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vBViNsuruN7s5WgBsa3dW2bp\">\n                \n              </figure>\n              \n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Here is a trapezoid. <span class=\"math math-repaired\" data-png-file-id=\"81\">\\(a\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span> represent the lengths of its bottom and top sides. The segment labeled <span class=\"math math-repaired\" data-png-file-id=\"55\">\\(h\\)</span> represents its height; it is perpendicular to both the top and bottom sides. </p>\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27301\" data-record-model=\"ImageFile\"><img alt=\"Trapezoid, bases labeled b and a, height labeled h\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/L43tLW2pLBUEqdvNevXBDENH\">\n                      \n                    </figure>\n                    <p>Apply area-reasoning strategies—decomposing, rearranging, duplicating, etc.—on the trapezoid so that you have one or more shapes with areas that you already know how to find. Use the shapes to help you write a formula for the area of a trapezoid. Show your reasoning.</p>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"11.4: Pinwheel","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Find the area of the shaded region in square units. Show your reasoning.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27306\" data-record-model=\"ImageFile\"><img alt=\"A shaded polygon on a grid.\" class=\"h-max-height--15-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/rhx6K4hGFt8uVJ8CZR3N1tHZ\">\n                \n              </figure>\n              \n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-video-link\" data-embedder-target=\"web\" data-record-id=\"145\" data-record-model=\"VideoLink\"><iframe allowfullscreen=\"true\" frameborder=\"0\" height=\"360\" mozillaallowfullscreen=\"true\" safariallowfullscreen=\"true\" src=\"https://player.vimeo.com/video/443554693\" width=\"640\"></iframe>\n                <figcaption class=\"c-figcaption\">Video <em>VLS G6U1V1 Reasoning to Find Area (Lessons 1–3, 11)</em> available at <a href=\"https://player.vimeo.com/video/443554693\">https://player.vimeo.com/video/443554693</a>.</figcaption>\n              </figure>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all </strong>the polygons.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29404\" data-record-model=\"ImageFile\"><img alt=\"Six figures labeled A, B, C, D, E, F.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/zwbWtpTZeaa4mFmd8mjcGr1v\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>A</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>B</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>C</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>D</p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p>E</p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p>F</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Mark each vertex with a large dot. How many edges and vertices does this polygon have?</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29405\" data-record-model=\"ImageFile\"><img alt=\"12 sided polygon resembling a star\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/LD3y7y9YwqxkdKrPQXJWQXff\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Find the area of this trapezoid. Explain or show your strategy.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29406\" data-record-model=\"ImageFile\"><img alt=\"Trapezoid, bases 8 and 4 units. Height 3 units.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/avt3EEccdUpiJ2xz7Gduju2X\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Lin and Andre used different methods to find the area of a regular hexagon with 6-inch sides. Lin decomposed the hexagon into six identical, equilateral triangles. Andre decomposed the hexagon into a rectangle and two triangles.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29411\" data-record-model=\"ImageFile\"><img alt=\"2 identical hexagons labeled Lin’s method and Andre’s method.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/zS6MDGFZ6zDKUinTZDYPAZFE\">\n              \n            </figure>\n            <p>Find the area of the hexagon using each person’s method. Show your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>Identify a base and a corresponding height that can be used to find the area of this triangle. Label the base <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span> and the corresponding height <span class=\"math math-repaired\" data-png-file-id=\"55\">\\(h\\)</span>.</p>\n                <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29396\" data-record-model=\"ImageFile\"><img alt=\"A triangle on a grid.\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/XJV84VnoF4BnG8VdoMCGuP2o\">\n                  \n                </figure>\n              </li>\n              <li>\n                <p>Find the area of the triangle. Show your reasoning.</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 9.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>On the grid, draw three different triangles with an area of 8 square units. Label the base and height of each triangle.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27847\" data-record-model=\"ImageFile\"><img alt=\"A blank coordinate plane with 16 evenly spaced horizontal units and 12 evenly spaced vertical units.\" class=\"h-max-height--13-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Mtje8WXsjQDE9fQ8VtAvNX1D\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 10.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l12","number":12,"title":"What is Surface Area?","introText":"Let’s cover the surfaces of some three-dimensional objects.","activities":[{"title":"12.1: Covering the Cabinet (Part 1)","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Your teacher will show you a video about a cabinet or some pictures of it.</p>\n              <p>Estimate an answer to the question: How many sticky notes would it take to cover the cabinet, excluding the bottom?</p>\n            </div>"},{"title":"12.2: Covering the Cabinet (Part 2)","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Earlier, you learned about a cabinet being covered with sticky notes.</p>\n              <ol>\n                <li>How could you find the actual number of sticky notes it will take to cover the cabinet, excluding the bottom? What information would you need to know?\n                </li>\n                <li>Use the information you have to find the number of sticky notes to cover the cabinet. Show your reasoning.\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>How many sticky notes are needed to cover the outside of 2 cabinets pushed together (including the bottom)? What about 3 cabinets? 20 cabinets?</p>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"12.3: Building with Snap Cubes","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here is a rectangular prism built from 12 cubes:</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27313\" data-record-model=\"ImageFile\"><img alt=\"rectangular prism. 3 faces shown. \" class=\"h-max-height--14-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Wou8S6nVj6fVSAQMRLpepqPJ\">\n                \n              </figure>\n              <p>It has six <strong>faces</strong>, but you can only see three of them in the sketch. It has a <strong>surface area</strong> of 32 square units.</p>\n              <p>The applet has 12 blocks, too. They are all in the same spot on the screen, like a hidden stack of blocks. You will always know where the stack is because it sits on a gray square. To use a block, drag the red point to move it. Click on the red points to change from left/right movement to up/down movement.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27314\" data-record-model=\"ImageFile\"><img alt='Two rectanglular prisms. Prism on left labeled \"move left and right.\" Prism on right labeled \"move up and down.\"' class=\"h-max-height--14-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/7nT3SMZhNunGxgnVZpG4tBc4\">\n                \n              </figure>\n              <p>Use all 12 cubes to build a different rectangular prism (with different edge lengths than shown in the prism here). You can turn the view to see all of the faces of your figure.</p>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4271\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"\",\"height\":\"\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"showToolBar\":true,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4271-1\"></div>\n              </div>\n              <ol>\n                <li>How many faces does your figure have?</li>\n                <li>What is the surface area of your figure in square units?</li>\n              </ol>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ul>\n                <li>The <strong>surface area</strong> of a figure (in square units) is the number of unit squares it takes to cover the entire surface without gaps or overlaps.</li>\n                <li>If a three-dimensional figure has flat sides, the sides are called <strong>faces</strong>.</li>\n                <li>The surface area is the total of the areas of the faces.</li>\n              </ul>\n              <p>For example, a rectangular prism has six faces. The surface area of the prism is the total of the areas of the six rectangular faces.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26734\" data-record-model=\"ImageFile\"><img alt=\"rectangular prism, length = 3 units, width = 2 units, height = 4 units.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/qUPjMazm1FEbDdpkzQAb96ra\">\n                \n              </figure>\n              <p>So the surface area of a rectangular prism that has edge-lengths 2 cm, 3 cm, and 4 cm has a surface area of <span class=\"math math-displayed math-repaired\">\\(\\displaystyle (2\\boldcdot 3)+ (2\\boldcdot 3) + (2\\boldcdot 4) + (2\\boldcdot 4) + (3\\boldcdot 4) + (3\\boldcdot 4)\\)</span> or 52 square centimeters.</p>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>What is the surface area of this rectangular prism?</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29412\" data-record-model=\"ImageFile\"><img alt=\"2 by 4 by 4 unit rectangular prism \" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/iJPx5maTn7dLmfeLiFB8SMyR\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>16 square units</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>32 square units</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>48 square units</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>64 square units</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Which description can represent the surface area of this trunk?</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29418\" data-record-model=\"ImageFile\"><img alt=\"Photograph of a treasure chest\" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/8nxjsjChyLETVonsip83oSEk\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>The number of square inches that cover the top of the trunk.</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>The number of square feet that cover all the outside faces of the trunk.</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>The number of square inches of horizontal surface inside the trunk.</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>The number of cubic feet that can be packed inside the trunk.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Which figure has a greater surface area?</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29413\" data-record-model=\"ImageFile\"><img alt=\"Figure A 5 cubes arranged in L shape. Figure B 5 cubes arranged in a cross shape.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/sPGRHqKeXSshRkagMijtMNZD\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>A rectangular prism is 4 units high, 2 units wide, and 6 units long. What is its surface area in square units? Explain or show your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Draw an example of each of these triangles on the grid.</p>\n            <ol>\n              <li>A right triangle with an area of 6 square units.</li>\n              <li>An acute triangle with an area of 6 square units.</li>\n              <li>An obtuse triangle with an area of 6 square units.</li>\n            </ol>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27247\" data-record-model=\"ImageFile\"><img alt=\"Image of a grid.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vupNoA5g96AkAtsSrCipKyG6\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 9.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Find the area of triangle <span class=\"math math-repaired\" data-png-file-id=\"35335\">\\(MOQ\\)</span> in square units. Show your reasoning.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29403\" data-record-model=\"ImageFile\"><img alt=\"Triangle MOQ enclosed in rectangle MNPR.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/fEgoXKo5Wd1q28drYyPTvrPz\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 10.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>Find the area of this shape. Show your reasoning.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29349\" data-record-model=\"ImageFile\"><img alt=\"A four-sided shape on a grid, with two sides that drop 5 units as they cross 5 units and meet at a right angle, and two sides that drop two units as they cross 5 units.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/PpH31cWnsGuAPB8XuXyy4ZWn\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 3.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l13","number":13,"title":"Polyhedra","introText":"Let’s investigate polyhedra.","activities":[{"title":"13.1: What are Polyhedra?","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here are pictures that represent <strong>polyhedra</strong>:</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27318\" data-record-model=\"ImageFile\"><img alt=\"5 polyhedra\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/ivnwGJY2c7xUdUPP6sffcV8V\">\n                \n              </figure>\n              <p>Here are pictures that do <em>not</em> represent polyhedra:</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27319\" data-record-model=\"ImageFile\"><img alt=\"a sphere, a cylinder, a strip with 3 twists joined end-to-end, and an open-top box.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Bx8aYRM6zzsXyan5Req9dn7p\">\n                \n              </figure>\n              \n              <ol>\n                <li>\n                  <p>Your teacher will give you some figures or objects. Sort them into polyhedra and non-polyhedra.</p>\n                </li>\n                <li>What features helped you distinguish the polyhedra from the other figures?\n                </li>\n              </ol>\n            </div>"},{"title":"13.2: Prisms and Pyramids","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>Here are some polyhedra called <strong>prisms</strong>.\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27320\" data-record-model=\"ImageFile\"><img alt=\"Six prisms, labeled A, B, C, D, E, and F.\" class=\"h-max-height--14-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/A7wJLi84a3RwTZGJJwpZdHew\">\n                    \n                  </figure>\n                  <p>Here are some polyhedra called <strong>pyramids</strong>.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27321\" data-record-model=\"ImageFile\"><img alt=\"Four polyhedral labeled P, Q, R, and S. Each figure has a base and a number of sides which share a single vertex.\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/qmZvgYWKF56hkHhLUzFZNePR\">\n                    \n                  </figure>\n                  <ol>\n                    <li>Look at the prisms. What are their characteristics or features? \n                    </li>\n                    <li>Look at the pyramids. What are their characteristics or features?\n                    </li>\n                  </ol>\n                </li>\n                <li>Which of these <strong>nets</strong> can be folded into Pyramid P? Select all that apply.\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27322\" data-record-model=\"ImageFile\"><img alt=\"Three nets. \" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/stnBtGCQ1ZaPNjbgrPRtqzxo\">\n                    \n                  </figure>\n                </li>\n                <li>\n                  <p>Your teacher will give your group a set of polygons and assign a polyhedron.</p>\n                  <ol>\n                    <li>Decide which polygons are needed to compose your assigned polyhedron. List the polygons and how many of each are needed.\n                    </li>\n                    <li>\n                      <p>Arrange the cut-outs into a net that, if taped and folded, can be assembled into the polyhedron. Sketch the net. If possible, find more than one way to arrange the polygons (show a different net for the same polyhedron).</p>\n                    </li>\n                  </ol>\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>What is the smallest number of faces a polyhedron can possibly have? Explain how you know.</p>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"13.3: Assembling Polyhedra","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Your teacher will give you the net of a polyhedron. Cut out the net, and fold it along the edges to assemble a polyhedron. Tape or glue the flaps so that there are no unjoined edges.</p>\n                </li>\n                <li>How many <strong>vertices</strong>, <strong>edges</strong>, and <strong>faces</strong> are in your polyhedron?\n                </li>\n              </ol>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>A <strong>polyhedron</strong> is a three-dimensional figure composed of faces. Each face is a filled-in polygon and meets only one other face along a complete edge. The ends of the edges meet at points that are called vertices.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26735\" data-record-model=\"ImageFile\"><img alt=\"A prism and pyramid with labels indicating an edge, vertex, and face on each.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Qj2t8nenRUQjBrCK9U2KiLjN\">\n                \n              </figure>\n              <p>A polyhedron<strong> </strong>always encloses a three-dimensional region.</p>\n              <p>The plural of polyhedron is polyhedra. Here are some drawings of polyhedra:</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26736\" data-record-model=\"ImageFile\"><img alt=\"3 polyhedra, from left to right shapes resemble a house, drum, and star.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/GfQ8JwX1SE4PzXvvd3i9uQZv\">\n                \n              </figure>\n              \n              <p>A <strong>prism</strong> is a type of polyhedron with two identical faces that are parallel to each other and that are called <strong>bases</strong>. The bases are connected by a set of rectangles (or sometimes parallelograms).</p>\n              <p>A prism is named for the shape of its bases. For example, if the base is a pentagon, then it is called a “pentagonal prism.”</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26737\" data-record-model=\"ImageFile\"><img alt=\"A triangular prism, a pentagonal prism, and a rectangular prism.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/sbMntz5w5H5tuio8ypDDCKaR\">\n                \n              </figure>\n              <p>A <strong>pyramid</strong> is a type of polyhedron that has one special face called the base. All of the other faces are triangles that all meet at a single vertex.</p>\n              <p>A pyramid is named for the shape of its base. For example, if the base is a pentagon, then it is called a “pentagonal pyramid.”</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26738\" data-record-model=\"ImageFile\"><img alt=\"A rectangular pyramid, a hexagonal pyramid, a heptagonal pyramid, and a decagonal pyramid.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/QCViJ624cT6BsiVYVpno1GaC\">\n                \n              </figure>\n              <p>A <strong>net</strong> is a two-dimensional representation of a polyhedron. It is composed of polygons that form the faces of a polyhedron.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26739\" data-record-model=\"ImageFile\"><img alt=\"Six squares arranged with 4 in a row, 1 above the second square in the row, and one below the second square in the row.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/eqPZ3DWBFW12Q97WRkNQzUvx\">\n                      \n                    </figure>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--row-1 g--two-third\">\n                    <p>A cube has 6 square faces, so its net is composed of six squares, as shown here.</p>\n                    <p>A net can be cut out and folded to make a model of the polyhedron.</p>\n                  </div>\n                </div>\n              </div>\n              <p>In a cube, every face shares its edges with 4 other squares. In a net of a cube, not all edges of the squares are joined with another edge. When the net is folded, however, each of these open edges will join another edge.</p>\n              <p>It takes practice to visualize the final polyhedron by just looking at a net.</p>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the polyhedra.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29420\" data-record-model=\"ImageFile\"><img alt=\"Figure A rectangular pyramid. Figure B many sided polyhedron. Figure C cone. Figure D Prism with hexagon faces. Figure E sphere.\" class=\"h-max-height--13-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/w5KuSmm66D7KoaNLVa24nM9C\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>A</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>B</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>C</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>D</p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p>E</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>Is this polyhedron a prism, a pyramid, or neither? Explain how you know.</p>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                      <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29421\" data-record-model=\"ImageFile\"><img alt=\"Prism with octagons as faces.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/q1FdC3kYQkUGFVSnZfkswy2r\">\n                        \n                      </figure>\n                    </div>\n                    <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                      \n                    </div>\n                  </div>\n                </div>\n              </li>\n              <li>How many faces, edges, and vertices does it have?</li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--three-fourth g--content g--col-1 g--row-1\">\n                  <p>Tyler said this net cannot be a net for a square prism because not all the faces are squares.</p>\n                  <p>Do you agree with Tyler? Explain your reasoning.</p>\n                </div>\n                <div class=\"g--column g--one-fourth g--content g--col-2 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29426\" data-record-model=\"ImageFile\"><img alt=\"net. 4 adjacent rectangles. Square above rectangle 2 and beow rectangle 1.\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/qPD7z53XdqsNQyqVdhQ11nRp\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Explain why each of these triangles has an area of 9 square units.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29387\" data-record-model=\"ImageFile\"><img alt=\"Three triangles labeled A, B, and, C. Each triangle has a bas of 6 units and a height of 3 units.\" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/NQepdH7puEBLUkSc2JZToGG5\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 8.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>A parallelogram has a base of 12 meters and a height of 1.5 meters. What is its area?</p>\n              </li>\n              <li>A triangle has a base of 16 inches and a height of <span class=\"math math-repaired\" data-png-file-id=\"2240\">\\(\\frac18\\)</span> inches. What is its area?\n              </li>\n              <li>A parallelogram has an area of 28 square feet and a height of 4 feet. What is its base?\n              </li>\n              <li>A triangle has an area of 32 square millimeters and a base of 8 millimeters. What is its height?\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 9.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Find the area of the shaded region. Show or explain your reasoning.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29340\" data-record-model=\"ImageFile\"><img alt=\"Triangle shaded with a unshaded square located in the middle on the bottom.\" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/J1qEMcijroqnTp77iHX5Z1ZH\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 3.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l14","number":14,"title":"Nets and Surface Area","introText":"Let’s use nets to find the surface area of polyhedra.","activities":[{"title":"14.1: Matching Nets","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Each of the nets can be assembled into a polyhedron. Match each net with its corresponding polyhedron, and name the polyhedron. Be prepared to explain how you know the net and polyhedron go together.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27324\" data-record-model=\"ImageFile\"><img alt=\"Five nets of polyhedra labeled 1--5.\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/pVT1LjL5rUoZJTnLLcwRQKGF\">\n                \n              </figure>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27325\" data-record-model=\"ImageFile\"><img alt=\"Five polyhedra labeled A--E.\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/sAzq5Ab7DSnQQm3YqyF7QYmu\">\n                \n              </figure>\n              \n            </div>"},{"title":"14.2: Using Nets to Find Surface Area","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Name the polyhedron that each net would form when assembled.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27328\" data-record-model=\"ImageFile\"><img alt=\"Three nets on a grid, labeled A, B, and C.\" class=\"h-max-height--12-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Qa4rkgfXLZoLbBZYSBCfWZ7k\">\n                    \n                  </figure>\n                </li>\n                <li>Your teacher will give you the nets of three polyhedra. Cut out the nets and assemble the three-dimensional shapes.</li>\n                <li>Find the <strong>surface area</strong> of each polyhedron. Explain your reasoning clearly.\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <ol>\n                      <li>\n                        <p>For each net, decide if it can be assembled into a rectangular prism.</p>\n                        <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27326\" data-record-model=\"ImageFile\"><img alt=\"Four possible nets labeled A--D.\" class=\"h-max-height--12-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/8GaudPL9bjbDj6YnqYUxHeD4\">\n                          \n                        </figure>\n                      </li>\n                      <li>\n                        <p>For each net, decide if it can be folded into a triangular prism.</p>\n                        <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27327\" data-record-model=\"ImageFile\"><img alt=\"Four possible nets labeled A--D.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/h6tXFW731MM7guDMkUK5dUQU\">\n                          \n                        </figure>\n                      </li>\n                    </ol>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>A net of a <em>pyramid</em> has one polygon that is the base. The rest of the polygons are triangles. A pentagonal pyramid and its net are shown here.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26740\" data-record-model=\"ImageFile\"><img alt=\"The net for this pentagonal pyramid is a pentagon surrounded by triangles on each side.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/s6g27fuRAV7VKfDvEM2hJvgc\">\n                \n              </figure>\n              <p>A net of a <em>prism </em>has two copies of the polygon that is the base. The rest of the polygons are rectangles. A pentagonal prism and its net are shown here.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26741\" data-record-model=\"ImageFile\"><img alt=\"The net for this pentagonal prism is a pentagon surrounded by rectangles on each side with an additional pentagon attached to the opposite side of one of the rectangles.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/B4QS87DVvoU4mYeUrax9i6HC\">\n                \n              </figure>\n              <p>In a rectangular prism, there are three pairs of parallel and identical rectangles. Any pair of these identical rectangles can be the bases.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26742\" data-record-model=\"ImageFile\"><img alt='Three images of a rectangular prism. Each image has one set of opposing sides of the polyhedron shaded and labeled “base.\"' class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/9zBMNwWRkU4tbW7N9drsBwWV\">\n                \n              </figure>\n              <p>Because a net shows all the faces of a polyhedron, we can use it to find its surface area. For instance, the net of a rectangular prism shows three pairs of rectangles: 4 units by 2 units, 3 units by 2 units, and 4 units by 3 units.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26743\" data-record-model=\"ImageFile\"><img alt=\"A polyhedron made up of six rectangles. Two rectangles are 8 square units in area, 2 are 6 square units, and 2 are 12 square units.\" class=\"h-max-height--12-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/QCuqjYrgRH3QmiyvRThQGunf\">\n                \n              </figure>\n              <p>The <strong>surface area</strong> of the rectangular prism is 52 square units because <span class=\"math math-repaired\">\\(8+8+6+6+12+12=52\\)</span>.</p>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Can this net be assembled into a cube? Explain how you know. Label parts of the net with letters or numbers if it helps your explanation.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29431\" data-record-model=\"ImageFile\"><img alt=\"Net of cube \" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/TcyrwfChUcodqgeebQ5CWMgC\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>What polyhedron can be assembled from this net? Explain how you know.</p>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                      <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29435\" data-record-model=\"ImageFile\"><img alt=\"net on a grid. \" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/wPpELnXULtgwVmsrWEdMPm4u\">\n                        \n                      </figure>\n                    </div>\n                    <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                      \n                    </div>\n                  </div>\n                </div>\n              </li>\n              <li>Find the surface area of this polyhedron. Show your reasoning.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Here are two nets. Mai said that both nets can be assembled into the same triangular prism. Do you agree? Explain or show your reasoning.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29436\" data-record-model=\"ImageFile\"><img alt=\"2 nets labeled A and B. A is composed of 2 triangular and 3 rectangular faces. B is composed of the same faces, but they are arranged differently.\" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/iZiwj6jV2imycgobWmjEHot1\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <p>Here are two three-dimensional figures.</p>\n                  <p>Tell whether each of the following statements describes Figure A, Figure B, both, or neither.</p>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29422\" data-record-model=\"ImageFile\"><img alt=\"Figure A triangular prism. Figure B triangular pyramid.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/GMeWfd8yn4mH4Hm3EvM9TK2Y\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n            <ol>\n              <li>This figure is a polyhedron.</li>\n              <li>This figure has triangular faces.</li>\n              <li>There are more vertices than edges in this figure.</li>\n              <li>This figure has rectangular faces.</li>\n              <li>This figure is a pyramid.</li>\n              <li>There is exactly one face that can be the base for this figure.</li>\n              <li>The base of this figure is a triangle.</li>\n              <li>This figure has two identical and parallel faces that can be the base.</li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 13.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> units that can be used for surface area. </p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>square meters</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>feet</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>centimeters</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>cubic inches</p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p>square inches</p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p>square feet</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 12.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Find the area of this polygon. Show your reasoning.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29408\" data-record-model=\"ImageFile\"><img alt=\"An image of a 7-sided polygon. The bottom side of the polygon is six units long, and extends out to a total width of 10 units, and a central height of 6 units.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/wkUVdNnfsPBeyrgZdZo4PULs\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 11.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l15","number":15,"title":"More Nets, More Surface Area","introText":"Let’s draw nets and find the surface area of polyhedra.","activities":[{"title":"15.1: Notice and Wonder: Wrapping Paper","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Kiran is wrapping this box of sports cards as a present for a friend.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27330\" data-record-model=\"ImageFile\"><img alt=\"A prism with base length labeled 4 inches and base width labeled 2.5 inches.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/S4pMvqUH6Z1z3ae4inkFNbrH\">\n                \n              </figure>\n              <p>What do you notice? What do you wonder?</p>\n            </div>"},{"title":"15.2: Building Prisms and Pyramids","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Your teacher will give you a drawing of a polyhedron. You will draw its net and calculate its surface area. </p>\n              <ol>\n                <li>\n                  <p>What polyhedron do you have?</p>\n                </li>\n                <li>\n                  <p>Study your polyhedron. Then, draw its net on graph paper. Use the side length of a grid square as the unit.</p>\n                </li>\n                <li>\n                  <p>Label each polygon on the net with a name or number.</p>\n                </li>\n                <li>\n                  <p>Find the surface area of your polyhedron. Show your thinking in an organized manner so that it can be followed by others.</p>\n                </li>\n              </ol>\n            </div>"},{"title":"15.3: Comparing Boxes","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here are the nets of three cardboard boxes that are all rectangular prisms. The boxes will be packed with 1-centimeter cubes. All lengths are in centimeters.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27333\" data-record-model=\"ImageFile\"><img alt=\"Three nets labeled A--C.\" class=\"h-max-height--24-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/XcCkwzWdEAybnbL7G4LStmD4\">\n                \n              </figure>\n              <ol>\n                <li>Compare the surface areas of the boxes. Which box will use the least cardboard? Show your reasoning.\n                </li>\n                <li>Now compare the volumes of these boxes in cubic centimeters. Which box will hold the most 1-centimeter cubes? Show your reasoning. \n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Figure C shows a net of a cube. Draw a different net of a cube. Draw another one.  And then another one. How many different nets can be drawn and assembled into a cube?</p>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-video-link\" data-embedder-target=\"web\" data-record-id=\"148\" data-record-model=\"VideoLink\"><iframe allowfullscreen=\"true\" frameborder=\"0\" height=\"360\" mozillaallowfullscreen=\"true\" safariallowfullscreen=\"true\" src=\"https://player.vimeo.com/video/443561431\" width=\"640\"></iframe>\n                <figcaption class=\"c-figcaption\">Video <em>VLS G6U1V4 Surface Area (Lessons 12–15)</em> available at <a href=\"https://player.vimeo.com/video/443561431\">https://player.vimeo.com/video/443561431</a>.</figcaption>\n              </figure>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Jada drew a net for a polyhedron and calculated its surface area.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29438\" data-record-model=\"ImageFile\"><img alt=\"Triangular prism, dimensions and areas of faces provided.\" class=\"h-max-height--15-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/aTqZDMUAzxd1eDL4TR7ZKjRQ\">\n              \n            </figure>\n            <ol>\n              <li>What polyhedron can be assembled from this net?</li>\n              <li>Jada made some mistakes in her area calculation. What were the mistakes?\n              </li>\n              <li>Find the surface area of the polyhedron. Show your reasoning.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>A cereal box is 8 inches by 2 inches by 12 inches. What is its surface area? Show your reasoning. If you get stuck, consider drawing a sketch of the box or its net and labeling the edges with their measurements.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Twelve cubes are stacked to make this figure.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29416\" data-record-model=\"ImageFile\"><img alt=\"Steps, bottom row 3 cubes, middle row 2 cubes, top row 1 cube\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/YLsysrkLAdrxDKCJ8cJoJCmW\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--column g--two-third g--content g--col-2 g--row-1\">\n                  <ol>\n                    <li>What is its surface area?\n                    </li>\n                    <li>How would the surface area change if the top two cubes are removed?</li>\n                  </ol>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 12.)</span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Here are two polyhedra and their nets. Label all edges in the net with the correct lengths.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29444\" data-record-model=\"ImageFile\"><img alt=\"Two polyhedra labeled A and B. Polyhedron A has sides labeled 5, 4, and 10. Polyhedron B has sides labeled 4, 10, 13, 13, and 13.\" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/2Xfnskoyz3sRGdqASHzMTgCW\">\n              \n            </figure>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29445\" data-record-model=\"ImageFile\"><img alt=\"Figure A net of rectangular prism. Figure B rectangular pyramid.\" class=\"h-max-height--13-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/a2CJ1dZxE926NEUemxsATXTZ\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>What three-dimensional figure can be assembled from the net?</p>\n                <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29429\" data-record-model=\"ImageFile\"><img alt=\"Net of a square pyramid. Base 4 by 4. Height of triangular faces = 5.\" class=\"h-max-height--16-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/aoNoJyPFJGy84NEmCBg6YToj\">\n                  \n                </figure>\n              </li>\n              <li>What is the surface area of the figure? (One grid square is 1 square unit.)</li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 14.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l16","number":16,"title":"Distinguishing Between Surface Area and Volume","introText":"Let’s contrast surface area and volume.","activities":[{"title":"16.1: Attributes and Their Measures","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>For each quantity, choose one or more appropriate units of measurement.</p>\n              <p>For the last two, think of a quantity that could be appropriately measured with the given units.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--column g--two-third g--content g--col-1 g--row-1\">\n                    <div>\n                      <p><u>Quantities</u></p>\n                      <ol>\n                        <li>Perimeter of a parking lot:</li>\n                        <li>Volume of a semi truck:</li>\n                        <li>Surface area of a refrigerator:</li>\n                        <li>Length of an eyelash:</li>\n                        <li>Area of a state:</li>\n                        <li>Volume of an ocean:</li>\n                        <li>________________________: miles</li>\n                        <li>________________________: cubic meters</li>\n                      </ol>\n                    </div>\n                  </div>\n                  <div class=\"g--column g--one-third g--content g--col-2 g--row-1\">\n                    <div>\n                      <p><u>Units</u></p>\n                      <ul>\n                        <li>millimeters (mm)</li>\n                        <li>feet (ft)</li>\n                        <li>meters (m)</li>\n                        <li>square inches (sq in)</li>\n                        <li>square feet (sq ft)</li>\n                        <li>square miles (sq mi)</li>\n                        <li>cubic kilometers (cu km)</li>\n                        <li>cubic yards (cu yd)</li>\n                      </ul>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"16.2: Building with 8 Cubes","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>This applet has 16 cubes in its hidden stack. Build two different shapes using 8 cubes for each.</p>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4272\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"\",\"height\":\"\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"showToolBar\":true,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4272-1\"></div>\n              </div>\n              <p>For each shape, determine the following information and write it on a sticky note.</p>\n              <ul>\n                <li>Give a name or a label (e.g., Mae’s First Shape or Eric’s Steps).</li>\n                <li>Determine its volume.</li>\n                <li>Determine its surface area.</li>\n              </ul>\n            </div>"},{"title":"16.3: Comparing Prisms Without Building Them","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Three rectangular prisms each have a height of 1 cm.</p>\n              <ul>\n                <li>Prism A has a base that is 1 cm by 11 cm.</li>\n                <li>Prism B has a base that is 2 cm by 7 cm.</li>\n                <li>Prism C has a base that is 3 cm by 5 cm.</li>\n              </ul>\n              <ol>\n                <li>\n                  <p>Find the surface area and volume of each prism. Use the dot paper to draw the prisms, if needed.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27337\" data-record-model=\"ImageFile\"><img alt=\"isometric dot paper\" class=\"h-max-height--20-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/aMWZbSqxXtdjghqypASHKVz1\">\n                    \n                  </figure>\n                </li>\n                <li>Analyze the volumes and surface areas of the prisms. What do you notice? Write 1 or 2 observations about them.\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Can you find more examples of prisms that have the same surface areas but different volumes? How many can you find?</p>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--row-1 g--two-third\">\n                    <p><em>Length</em> is a one-dimensional attribute of a geometric figure. We measure lengths using units like millimeters, centimeters, meters, kilometers, inches, feet, yards, and miles.</p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26746\" data-record-model=\"ImageFile\"><img alt=\"pencil with ruler along length\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/fRyqByhNjpXPczswSL6U47cw\">\n                      \n                    </figure>\n                  </div>\n                </div>\n                <div class=\"g--row g--row-2\">\n                  <div class=\"g--col-1 g--column g--content g--row-2 g--two-third\">\n                    <p><em>Area</em> is a two-dimensional attribute. We measure area in square units. For example, a square that is 1 centimeter on each side has an area of 1 square centimeter.</p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-2\">\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26747\" data-record-model=\"ImageFile\"><img alt=\"Rectangular widow with rulers along the length and width\" class=\"h-max-height--13-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/UbgQ4UkWqLtj1W2QRcLDzCNf\">\n                      \n                    </figure>\n                  </div>\n                </div>\n                <div class=\"g--row g--row-3\">\n                  <div class=\"g--col-1 g--column g--content g--row-3 g--two-third\">\n                    <p><em>Volume</em> is a three-dimensional attribute. We measure volume in cubic units. For example, a cube that is 1 kilometer on each side has a volume of 1 cubic kilometer.</p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-3\">\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26748\" data-record-model=\"ImageFile\"><img alt=\"3 boxes stacked vertically, rulers along length, width, and height\" class=\"h-max-height--12-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/dMxUKqkukf8vrR4N7gUdZDFj\">\n                      \n                    </figure>\n                  </div>\n                </div>\n              </div>\n              <p>Surface area and volume are different attributes of three-dimensional figures. Surface area is a two-dimensional measure, while volume is a three-dimensional measure.</p>\n              <p>Two figures can have the same volume but different surface areas. For example:</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--row-1 g--two-third\">\n                    <ul>\n                      <li>A rectangular prism with side lengths of 1 cm, 2 cm, and 2 cm has a volume of 4 cu cm and a surface area of 16 sq cm.</li>\n                      <li>A rectangular prism with side lengths of 1 cm, 1 cm, and 4 cm has the same volume but a surface area of 18 sq cm.</li>\n                    </ul>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26749\" data-record-model=\"ImageFile\"><img alt=\"4 cubes arranged into two different rectangular prisms\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/TsBPC2C5AxA7M7ZuDDwTygKs\">\n                      \n                    </figure>\n                  </div>\n                </div>\n              </div>\n              <p>Similarly, two figures can have the same surface area but different volumes. </p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--row-1 g--two-third\">\n                    <ul>\n                      <li>A rectangular prism with side lengths of 1 cm, 1 cm, and 5 cm has a surface area of 22 sq cm and a volume of 5 cu cm.</li>\n                      <li>A rectangular prism with side lengths of 1 cm, 2 cm, and 3 cm has the same surface area but a volume of 6 cu cm.</li>\n                    </ul>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26750\" data-record-model=\"ImageFile\"><img alt=\"2 different rectangular prisms\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/g2AGpFdDxFXfXMFkJGTJuLTD\">\n                      \n                    </figure>\n                  </div>\n                </div>\n              </div>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Match each quantity with an appropriate unit of measurement.</p>\n          </div>\n          <div class=\"im-c-columns\">\n            <section class=\"im-c-link-menu\">\n              <div class=\"im-c-content\">A: \n                <p>The surface area of a tissue box</p>\n              </div>\n              <div class=\"im-c-content\">B: \n                <p>The amount of soil in a planter box</p>\n              </div>\n              <div class=\"im-c-content\">C: \n                <p>The area of a parking lot</p>\n              </div>\n              <div class=\"im-c-content\">D: \n                <p>The length of a soccer field</p>\n              </div>\n              <div class=\"im-c-content\">E: \n                <p>The volume of a fish tank</p>\n              </div>\n            </section>\n            <section class=\"im-c-link-menu\">\n              <div class=\"im-c-content\">1: \n                <p>Square meters</p>\n              </div>\n              <div class=\"im-c-content\">2: \n                <p>Yards</p>\n              </div>\n              <div class=\"im-c-content\">3: \n                <p>Cubic inches</p>\n              </div>\n              <div class=\"im-c-content\">4: \n                <p>Cubic feet</p>\n              </div>\n              <div class=\"im-c-content\">5: \n                <p>Square centimeters</p>\n              </div>\n            </section>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Here is a figure built from snap cubes.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29455\" data-record-model=\"ImageFile\"><img alt=\"4 snap cubes forming a rectangular prism, 1 by 1 by 4.\" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/6BtRTBMq8kjwPSxHQbetVAZJ\">\n              \n            </figure>\n            <ol>\n              <li>Find the volume of the figure in cubic units.\n              </li>\n              <li>Find the surface area of the figure in square units.\n              </li>\n              <li>True or false: If we double the number of cubes being stacked, both the volume and surface area will double. Explain or show how you know.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Lin said, “Two figures with the same volume also have the same surface area.”</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                  <ol>\n                    <li>Which two figures suggest that her statement is true?</li>\n                    <li>Which two figures could show that her statement is <em>not</em> true?</li>\n                  </ol>\n                </div>\n                <div class=\"g--column g--two-third g--content g--col-2 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29456\" data-record-model=\"ImageFile\"><img alt=\"5 figures composed of unit cubes, labeled A, B, C, D, E.\" class=\"h-max-height--13-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/pxZ7pBkxbcrSDz66NpRXs64t\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Draw a pentagon (five-sided polygon) that has an area of 32 square units. Label all relevant sides or segments with their measurements, and show that the area is 32 square units.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 11.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>Draw a net for this rectangular prism.</p>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                      <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29439\" data-record-model=\"ImageFile\"><img alt=\"2 by 5 by 10 centimeter rectangular prism.\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/BAZtHgy4aBf9kccMQJeNa7Ay\">\n                        \n                      </figure>\n                    </div>\n                    <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                      \n                    </div>\n                  </div>\n                </div>\n              </li>\n              <li>Find the surface area of the rectangular prism.</li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 15.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l17","number":17,"title":"Squares and Cubes","introText":"Let’s investigate perfect squares and perfect cubes.","activities":[{"title":"17.1: Perfect Squares","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--row-1 g--three-fourth\">\n                    <ol>\n                      <li>The number 9 is a perfect <strong>square</strong>. Find four numbers that are perfect squares and two numbers that are not perfect squares. \n                      </li>\n                      <li>A square has side length 7 in. What is its area?\n                      </li>\n                      <li>The area of a square is 64 sq cm. What is its side length?\n                      </li>\n                    </ol>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-fourth g--row-1\">\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27340\" data-record-model=\"ImageFile\"><img alt=\"Nine squares arranged into a 3 by 3 square.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vbYRHXxbzFs3gFjFsdhXCwCy\">\n                      \n                    </figure>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"17.2: Building with 32 Cubes","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Use the 32 snap cubes in the applet’s hidden stack to build the largest single cube you can. Each small cube has side length of 1 unit.</p>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4273\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"\",\"height\":\"\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"showToolBar\":true,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4273-1\"></div>\n              </div>\n              <ol>\n                <li>How many snap cubes did you use?</li>\n                <li>What is the side length of the cube you built?</li>\n                <li>What is the area of each face of the built cube? Show your reasoning.</li>\n                <li>What is the volume of the built cube? Show your reasoning.</li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>This applet has a total of 64 snap cubes. Build the largest single cube you can.</p>\n                    <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"5469\" data-record-model=\"GeogebraFile\">\n                      <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"680\",\"height\":\"623\",\"enableRightClick\":true,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":true,\"showMenuBar\":false,\"showToolBar\":true,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                      <div class=\"ggb-applet-container\" id=\"GeogebraFile-5469-2\"></div>\n                    </div>\n                    <ol>\n                      <li>How many snap cubes did you use?    </li>\n                      <li>What is the edge length of the new cube you built?</li>\n                      <li>What is the area of each face of this built cube? Show your reasoning.    </li>\n                      <li>What is the volume of this built cube? Show your reasoning.</li>\n                    </ol>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"17.3: Perfect Cubes","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--row-1 g--three-fourth\">\n                    <ol>\n                      <li>The number 27 is a perfect <strong>cube</strong>. Find four other numbers that are perfect cubes and two numbers that are <em>not</em> perfect cubes.\n                      </li>\n                      <li>A cube has side length 4 cm. What is its volume?\n                      </li>\n                      <li>A cube has side length 10 inches. What is its volume?\n                      </li>\n                      <li>A cube has side length <span class=\"math math-repaired\" data-png-file-id=\"833\">\\(s\\)</span> units. What is its volume?\n                      </li>\n                    </ol>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-fourth g--row-1\">\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27342\" data-record-model=\"ImageFile\"><img alt=\"A 3 by 3 by 3 cube.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/5kiHo1he6M2mUuE7epcypWKz\">\n                      \n                    </figure>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"17.4: Introducing Exponents","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Make sure to include correct units of measure as part of each answer.</p>\n              <ol>\n                <li>A square has side length 10 cm. Use an <strong>exponent</strong> to express its area.</li>\n                <li>The area of a square is <span class=\"math math-repaired\" data-png-file-id=\"9276\">\\(7^2\\)</span> sq in. What is its side length?</li>\n                <li>The area of a square is 81 m<sup>2</sup>. Use an exponent to express this area.</li>\n                <li>A cube has edge length 5 in. Use an exponent to express its volume.</li>\n                <li>The volume of a cube is <span class=\"math math-repaired\" data-png-file-id=\"3150\">\\(6^3\\)</span> cm<sup>3</sup>. What is its edge length?</li>\n                <li>A cube has edge length <span class=\"math math-repaired\" data-png-file-id=\"833\">\\(s\\)</span> units. Use an exponent to write an expression for its volume.\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>The number 15,625 is both a perfect square and a perfect cube. It is a perfect square because it equals <span class=\"math math-repaired\" data-png-file-id=\"41382\">\\(125^2\\)</span>. It is also a perfect cube because it equals <span class=\"math math-repaired\" data-png-file-id=\"41419\">\\(25^3\\)</span>. Find another number that is both a perfect square and a perfect cube. How many of these can you find?</p>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>When we multiply two of the same numbers together, such as <span class=\"math math-repaired\">\\(5\\boldcdot 5\\)</span>, we say we are <strong>squaring</strong> the number. We can write it like this: <span class=\"math math-displayed math-repaired\">\\(\\displaystyle 5^2\\)</span></p>\n              <p>Because <span class=\"math math-repaired\">\\(5\\boldcdot 5 = 25\\)</span>, we write <span class=\"math math-repaired\">\\(5^2 = 25\\)</span> and we say, “5 squared is 25.”</p>\n              <p>When we multiply three of the same numbers together, such as <span class=\"math math-repaired\">\\(4\\boldcdot 4 \\boldcdot 4\\)</span>, we say we are <strong>cubing</strong> the number. We can write it like this: <span class=\"math math-displayed math-repaired\">\\(\\displaystyle 4^3\\)</span></p>\n              <p>Because <span class=\"math math-repaired\">\\(4\\boldcdot 4\\boldcdot 4 = 64\\)</span>, we write <span class=\"math math-repaired\">\\(4^3 = 64\\)</span> and we say, “4 cubed is 64.”</p>\n              <p>We also use this notation for square and cubic units.</p>\n              <ul>\n                <li>A square with side length 5 inches has area 25 in<sup>2</sup>.</li>\n                <li>A cube with edge length 4 cm has volume 64 cm<sup>3</sup>.</li>\n              </ul>\n              <p>To read 25 in<sup>2</sup>, we say “25 square inches,” just like before.</p>\n              <p>The area of a square with side length 7 kilometers is <span class=\"math math-repaired\">\\(7^2\\)</span> km<sup>2</sup>. The volume of a cube with edge length 2 millimeters is <span class=\"math math-repaired\">\\(2^3\\)</span> mm<sup>3</sup>.</p>\n              <p>In general, the area of a square with side length <span class=\"math math-repaired\">\\(s\\)</span> is <span class=\"math math-repaired\">\\(s^2\\)</span>, and the volume of a cube with edge length <span class=\"math math-repaired\">\\(s\\)</span> is <span class=\"math math-repaired\">\\(s^3\\)</span>.</p>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>What is the volume of this cube?</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29457\" data-record-model=\"ImageFile\"><img alt=\"cube, side length = 2 centimeters\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/wuFh2WDwbsqEFPgUaGCTbu8W\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>Decide if each number on the list is a perfect square.</p>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                      <p>16</p>\n                      <p>20</p>\n                      <p>25</p>\n                      <p>100</p>\n                    </div>\n                    <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                      <p>125</p>\n                      <p>144</p>\n                      <p>225</p>\n                      <p>10,000</p>\n                    </div>\n                  </div>\n                </div>\n              </li>\n              <li>Write a sentence that explains your reasoning.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>Decide if each number on the list is a perfect cube.</p>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                      <p>1</p>\n                      <p>3</p>\n                      <p>8</p>\n                      <p>9</p>\n                    </div>\n                    <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                      <p>27</p>\n                      <p>64</p>\n                      <p>100</p>\n                      <p>125</p>\n                    </div>\n                  </div>\n                </div>\n              </li>\n              <li>Explain what a perfect cube is.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>A square has side length 4 cm. What is its area?</p>\n              </li>\n              <li>\n                <p>The area of a square is 49 m<sup>2</sup>. What is its side length?</p>\n              </li>\n              <li>\n                <p>A cube has edge length 3 in. What is its volume?</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Prism A and Prism B are rectangular prisms.</p>\n            <ul class=\"list--compressed\">\n              <li>Prism A is 3 inches by 2 inches by 1 inch.</li>\n              <li>Prism B is 1 inch by 1 inch by 6 inches.</li>\n            </ul>\n            <p>Select <strong>all</strong> statements that are true about the two prisms.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>They have the same volume.</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p>They have the same number of faces.</p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>More inch cubes can be packed into Prism A than into Prism B.</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>The two prisms have the same surface area.</p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p>The surface area of Prism B is greater than that of Prism A.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 16.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>What polyhedron can be assembled from this net?</p>\n                <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29432\" data-record-model=\"ImageFile\"><img alt=\"Net of a triangular prism \" class=\"h-max-height--7-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/TqnGoHmQG9zdwMbqyxF3JPLe\">\n                  \n                </figure>\n              </li>\n              <li>\n                <p>What information would you need to find its surface area? Be specific, and label the diagram as needed.</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 14.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>Find the surface area of this triangular prism. All measurements are in meters.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29441\" data-record-model=\"ImageFile\"><img alt=\"trianglular prism with dimensions provided\" class=\"h-max-height--12-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/MPkEH7foGoYma7jqj4A3w54y\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 15.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l18","number":18,"title":"Surface Area of a Cube","introText":"Let’s write a formula to find the surface area of a cube.","activities":[{"title":"18.1: Exponent Review","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Select the greater expression of each pair without calculating the value of each expression. Be prepared to explain your choices.</p>\n              <ul>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"3156\">\\(10 \\boldcdot 3\\)</span>  or  <span class=\"math math-repaired\" data-png-file-id=\"3154\">\\(10^3\\)</span>\n                </li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"8154\">\\(13^2\\)</span>  or  <span class=\"math math-repaired\" data-png-file-id=\"41306\">\\(12 \\boldcdot 12\\)</span>\n                </li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"41338\">\\(97+97+97+97+97+97\\)</span>  or  <span class=\"math math-repaired\" data-png-file-id=\"41371\">\\(5 \\boldcdot 97\\)</span>\n                </li>\n              </ul>\n            </div>"},{"title":"18.2: The Net of a Cube","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>A cube has edge length 5 inches.</p>\n                  <ol>\n                    <li>\n                      <p>Draw a net for this cube, and label its sides with measurements.</p>\n                    </li>\n                    <li>What is the shape of each face?</li>\n                    <li>What is the area of each face?</li>\n                    <li>What is the surface area of this cube?</li>\n                    <li>What is the volume of this cube?</li>\n                  </ol>\n                </li>\n                <li>\n                  <p>A second cube has edge length 17 units.</p>\n                  <ol>\n                    <li>\n                      <p>Draw a net for this cube, and label its sides with measurements.</p>\n                    </li>\n                    <li>Explain why the area of each face of this cube is <span class=\"math math-repaired\">\\(17^2\\)</span> square units.\n                    </li>\n                    <li>Write an expression for the surface area, in square units.</li>\n                    <li>Write an expression for the volume, in cubic units.</li>\n                  </ol>\n                </li>\n              </ol>\n            </div>"},{"title":"18.3: Every Cube in the Whole World","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>A cube has edge length <span class=\"math math-repaired\" data-png-file-id=\"833\">\\(s\\)</span>.</p>\n              <ol>\n                <li>Draw a net for the cube.\n                </li>\n                <li>Write an expression for the area of each face. Label each face with its area.</li>\n                <li>Write an expression for the surface area.</li>\n                <li>Write an expression for the volume.\n                </li>\n              </ol>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-video-link\" data-embedder-target=\"web\" data-record-id=\"149\" data-record-model=\"VideoLink\"><iframe allowfullscreen=\"true\" frameborder=\"0\" height=\"360\" mozillaallowfullscreen=\"true\" safariallowfullscreen=\"true\" src=\"https://player.vimeo.com/video/443563211\" width=\"640\"></iframe>\n                <figcaption class=\"c-figcaption\">Video <em>VLS G6U1V5 Distinguishing between Surface Area and Volume (Lessons 16–18)</em> available at <a href=\"https://player.vimeo.com/video/443563211\">https://player.vimeo.com/video/443563211</a>.</figcaption>\n              </figure>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>What is the volume of a cube with edge length 8 in?</p>\n              </li>\n              <li>\n                <p>What is the volume of a cube with edge length <span class=\"math math-repaired\" data-png-file-id=\"3320\">\\(\\frac 13\\)</span> cm?</p>\n              </li>\n              <li>\n                <p>A cube has a volume of 8 ft<sup>3</sup>. What is its edge length?</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>What three-dimensional figure can be assembled from this net?</p>\n                <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29458\" data-record-model=\"ImageFile\"><img alt=\"six identical squares, net of a cube\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/YbJ3vMpLWyife3zk5Uq143pW\">\n                  \n                </figure>\n              </li>\n              <li>\n                <p>If each square has a side length of 61 cm, write an expression for the surface area and another for the volume of the figure.</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>Draw a net for a cube with edge length <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> cm.</p>\n              </li>\n              <li>\n                <p>What is the surface area of this cube?</p>\n              </li>\n              <li>\n                <p>What is the volume of this cube?</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Here is a net for a rectangular prism that was not drawn accurately.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29430\" data-record-model=\"ImageFile\"><img alt=\"Net of rectangular prism \" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/bUmunmyozsPNGJTzHpRjCfh6\">\n              \n            </figure>\n            <ol>\n              <li>Explain what is wrong with the net.\n              </li>\n              <li>Draw a net that can be assembled into a rectangular prism.\n              </li>\n              <li>Create another net for the same prism.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 14.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <p>State whether each figure is a polyhedron. Explain how you know.</p>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29424\" data-record-model=\"ImageFile\"><img alt=\"Two figures, A and B. Figure A is a cylinder, figure B is a prism with 7 sided polygons as faces.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/chNgvtLu2t4tGdWeBu3KmKs3\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 13.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Here is Elena’s work for finding the surface area of a rectangular prism that is 1 foot by 1 foot by 2 feet.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29419\" data-record-model=\"ImageFile\"><img alt=\"rectangular prism with student's work to calculate surface area shown\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/K5iG4SMkoptuXzyZubLPBfMe\">\n              \n            </figure>\n            <p>She concluded that the surface area of the prism is 296 square feet. Do you agree with her? Explain your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 12.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u01.l19","number":19,"title":"Designing a Tent","introText":"Let’s design some tents.","activities":[{"title":"19.1: Tent Design - Part 1","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Have you ever been camping?</p>\n              <p>You might know that sleeping bags are all about the same size, but tents come in a variety of shapes and sizes.</p>\n              <p>Your task is to design a tent to accommodate up to four people, and estimate the amount of fabric needed to make your tent. Your design and estimate must be based on the information given and have mathematical justification.</p>\n              <p>First, look at these examples of tents, the average specifications of a camping tent, and standard sleeping bag measurements. Talk to a partner about:</p>\n              <ul class=\"list--compressed\">\n                <li>Similarities and differences among the tents</li>\n                <li>Information that will be important in your designing process</li>\n                <li>The pros and cons of the various designs</li>\n              </ul>\n              <p><u>Tent Styles</u></p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27344\" data-record-model=\"ImageFile\"><img alt=\"5 tent designs\" class=\"h-max-height--14-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/RXbmRDufpjQWWtcPCEFG7hqv\">\n                \n              </figure>\n              <p><u>Tent Height Specifications</u></p>\n              <table border=\"1\" cellpadding=\"1\" cellspacing=\"1\">\n                <thead>\n                  <tr>\n                    <th scope=\"row\">height description</th>\n                    <th scope=\"col\">height of tent</th>\n                    <th scope=\"col\">notes</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr>\n                    <th scope=\"row\">sitting height</th>\n                    <td>3 feet</td>\n                    <td>Campers are able to sit, lie, or crawl inside tent.</td>\n                  </tr>\n                  <tr>\n                    <th scope=\"row\">kneeling height</th>\n                    <td>4 feet</td>\n                    <td>Campers are able to kneel inside tent. Found mainly in 3–4 person tents.</td>\n                  </tr>\n                  <tr>\n                    <th scope=\"row\">stooping height</th>\n                    <td>5 feet</td>\n                    <td>Campers are able to move around on their feet inside tent, but most campers will not be able to stand upright.</td>\n                  </tr>\n                  <tr>\n                    <th scope=\"row\">standing height</th>\n                    <td>6 feet</td>\n                    <td>Most adult campers are able to stand upright inside tent.</td>\n                  </tr>\n                  <tr>\n                    <th scope=\"row\">roaming height</th>\n                    <td>7 feet</td>\n                    <td>Adult campers are able to stand upright and walk around inside tent.</td>\n                  </tr>\n                </tbody>\n              </table>\n              <p><u>Sleeping Bag Measurements</u></p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27345\" data-record-model=\"ImageFile\"><img alt=\"A rectangle with side lengths 74 inches and 34 inches.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Sdg1PzrzXaCg6At7yHhTQag9\">\n                \n              </figure>\n              <ol>\n                <li>\n                  <p>Create and sketch your tent design. The tent must include a floor.</p>\n                </li>\n                <li>What decisions were important when choosing your tent design?\n                </li>\n                <li>\n                  <p>How much fabric do you estimate will be necessary to make your tent? Show your reasoning and provide mathematical justification.</p>\n                </li>\n              </ol>\n            </div>"},{"title":"19.2: Tent Design - Part 2","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Explain your tent design and fabric estimate to your partner or partners. Be sure to explain why you chose this design and how you found your fabric estimate.</p>\n                </li>\n                <li>\n                  <p>Compare the estimated fabric necessary for each tent in your group. Discuss the following questions:</p>\n                  <ul>\n                    <li>\n                      <p>Which tent design used the least fabric? Why?</p>\n                    </li>\n                    <li>\n                      <p>Which tent design used the most fabric? Why?</p>\n                    </li>\n                    <li>\n                      <p>Which change in design most impacted the amount of fabric needed for the tent? Why?</p>\n                    </li>\n                  </ul>\n                </li>\n              </ol>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </main>","glossary":[],"practiceProblems":[]}]};
